void ADFTypes::CMissionTriggerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    on_available_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        mission_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_loaded_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_accept_event.read(buffer);
    poi_placement.read(buffer);
    on_hidden_event.read(buffer);
    on_faded_out_event.read(buffer);
    min_cutscene_time = buffer.read_pod<float32>();
    buffer.skip(4);
    on_unavailable_event.read(buffer);
    do_prompt.read(buffer);
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    do_unprompt.read(buffer);
}

