void ADFTypes::CSoundOcclusionCylinderData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    inverted_normal = buffer.read_pod<int32>();
    occlusion_direct_path = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_enable.read(buffer);
    event_disable_dynamic_scaling.read(buffer);
    resolution = buffer.read_pod<int32>();
    buffer.skip(4);
    event_receive_matrix.read(buffer);
    dynamic_scaling = buffer.read_pod<float32>();
    enabled = buffer.read_pod<int32>();
    disable_xz0_disc = buffer.read_pod<int32>();
    buffer.skip(4);
    event_enable_xz0_disc.read(buffer);
    event_disable_xz0_disc.read(buffer);
    disable_xz1_disc = buffer.read_pod<int32>();
    occlusion_reverb_mix = buffer.read_pod<float32>();
    _exportable = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    event_enable_xz1_disc.read(buffer);
    event_disable_xz1_disc.read(buffer);
    event_disable.read(buffer);
    double_sided = buffer.read_pod<int32>();
    buffer.skip(4);
    event_enable_dynamic_scaling.read(buffer);
}

