void ADFTypes::CWillOWispData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    distance_per_sub_random = buffer.read_pod<float32>();
    max_travel_time = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_reach_end_event.read(buffer);
    distance_per_sub = buffer.read_pod<float32>();
    travel_time = buffer.read_pod<float32>();
    radius = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    speed = buffer.read_pod<float32>();
    use_path_if_possible = buffer.read_pod<int32>();
    buffer.skip(4);
}

