void ADFTypes::PartPhysicsMapping::read(IO::File& buffer) {
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    part_index = buffer.read_pod<int8>();
    world_collision_instance_id = buffer.read_pod<int8>();
    raycast_instance_id = buffer.read_pod<int8>();
    grandpa_world_instance_id = buffer.read_pod<int8>();
    grandpa_raycast_instance_id = buffer.read_pod<int8>();
    buffer.skip(1);
    world_collision_body_id = buffer.read_pod<int16>();
    raycast_body_id = buffer.read_pod<int16>();
    constraint_index = buffer.read_pod<int16>();
    buffer.skip(4);
}

void ADFTypes::PartPhysicsMapping::print(std::ostream &out) const {
    out << "name: " << name << "\n";
    out << "part_index: " << part_index << "\n";
    out << "world_collision_instance_id: " << world_collision_instance_id << "\n";
    out << "raycast_instance_id: " << raycast_instance_id << "\n";
    out << "grandpa_world_instance_id: " << grandpa_world_instance_id << "\n";
    out << "grandpa_raycast_instance_id: " << grandpa_raycast_instance_id << "\n";
    out << "world_collision_body_id: " << world_collision_body_id << "\n";
    out << "raycast_body_id: " << raycast_body_id << "\n";
    out << "constraint_index: " << constraint_index << "\n";
}

nlohmann::json ADFTypes::PartPhysicsMapping::to_json() const {
    nlohmann::json _res;
    _res["name"] = name;
    _res["part_index"] = part_index;
    _res["world_collision_instance_id"] = world_collision_instance_id;
    _res["raycast_instance_id"] = raycast_instance_id;
    _res["grandpa_world_instance_id"] = grandpa_world_instance_id;
    _res["grandpa_raycast_instance_id"] = grandpa_raycast_instance_id;
    _res["world_collision_body_id"] = world_collision_body_id;
    _res["raycast_body_id"] = raycast_body_id;
    _res["constraint_index"] = constraint_index;
    return _res;
}

