void ADFTypes::CSandWormUtilityData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    relative_bone = buffer.read_pod<int32>();
    spawn_attached_to_owner = buffer.read_pod<int32>();
    effect_emitter_submerge_ref.read(buffer);
    break_request_id = buffer.read_pod<int32>();
    release_main_chunk_on_shattering = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        local_spawn_vel_min[i] = buffer.read_pod<float32>();
    }
    break_request_custom_tag = buffer.read_pod<int32>();
    set_as_pass_thru = buffer.read_pod<int32>();
    coverage_explosion = buffer.read_pod<float32>();
    shattered_pieces_clone_factory_ref.read(buffer);
    spit_clone_factory_ref.read(buffer);
    effect_emitter_emerge_ref.read(buffer);
    disable_event.read(buffer);
    on_spawned_event.read(buffer);
    for(int i = 0; i < 3; ++i) {
        player_rel_vel_max[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    shatter_event.read(buffer);
    for(int i = 0; i < 3; ++i) {
        player_rel_vel_min[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        angular_vel_min[i] = buffer.read_pod<float32>();
    }
    spawn_event.read(buffer);
    clone_factory_ref.read(buffer);
    spawn_invisible = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        local_spawn_vel_max[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        angular_vel_max[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    force_despawn_event.read(buffer);
    effect_emitter_underground_ref.read(buffer);
    coverage_melee = buffer.read_pod<float32>();
    buffer.skip(4);
}

