void ADFTypes::DeformPoint::read(IO::File& buffer) {
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    name_hash = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        from_part = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    from_part_hash = buffer.read_pod<uint32>();
    from_part_index = buffer.read_pod<uint32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        skinned_to_part = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    skinned_to_part_hash = buffer.read_pod<uint32>();
    skinned_to_part_index = buffer.read_pod<uint32>();
    shape_key = buffer.read_pod<uint32>();
    has_custom_end = buffer.read_pod<uint8>();
    buffer.skip(3);
    deform_point_type.read(buffer);
    for(int i = 0; i < 16; ++i) {
        start_transform[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 16; ++i) {
        end_transform[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 4; ++i) {
        vertex_indices[i] = buffer.read_pod<int16>();
    }
    for(int i = 0; i < 4; ++i) {
        vertex_weights[i] = buffer.read_pod<float32>();
    }
}

void ADFTypes::DeformPoint::print(std::ostream &out) const {
    out << "name: " << name << "\n";
    out << "name_hash: " << name_hash << "\n";
    out << "from_part: " << from_part << "\n";
    out << "from_part_hash: " << from_part_hash << "\n";
    out << "from_part_index: " << from_part_index << "\n";
    out << "skinned_to_part: " << skinned_to_part << "\n";
    out << "skinned_to_part_hash: " << skinned_to_part_hash << "\n";
    out << "skinned_to_part_index: " << skinned_to_part_index << "\n";
    out << "shape_key: " << shape_key << "\n";
    out << "has_custom_end: " << has_custom_end << "\n";
    deform_point_type.print(out);
    out << "start_transform: \n";
    start_transform.print(out);
    out << "\n";
    out << "end_transform: \n";
    end_transform.print(out);
    out << "\n";
    out << "vertex_indices: \n";
    vertex_indices.print(out);
    out << "\n";
    out << "vertex_weights: \n";
    vertex_weights.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::DeformPoint::to_json() const {
    nlohmann::json _res;
    _res["name"] = name;
    _res["name_hash"] = name_hash;
    _res["from_part"] = from_part;
    _res["from_part_hash"] = from_part_hash;
    _res["from_part_index"] = from_part_index;
    _res["skinned_to_part"] = skinned_to_part;
    _res["skinned_to_part_hash"] = skinned_to_part_hash;
    _res["skinned_to_part_index"] = skinned_to_part_index;
    _res["shape_key"] = shape_key;
    _res["has_custom_end"] = has_custom_end;
    _res["deform_point_type"] = deform_point_type.to_json();
    _res["start_transform"] = start_transform.to_json();
    _res["end_transform"] = end_transform.to_json();
    _res["vertex_indices"] = vertex_indices.to_json();
    _res["vertex_weights"] = vertex_weights.to_json();
    return _res;
}

