void ADFTypes::CPlayerVortexGrenadeData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    implosion.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        hover_buff = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        damage_buff = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::CPlayerVortexGrenadeData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    implosion.print(out);
    out << "hover_buff: " << hover_buff << "\n";
    out << "name: " << name << "\n";
    out << "damage_buff: " << damage_buff << "\n";
}

nlohmann::json ADFTypes::CPlayerVortexGrenadeData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["implosion"] = implosion.to_json();
    _res["hover_buff"] = hover_buff;
    _res["name"] = name;
    _res["damage_buff"] = damage_buff;
    return _res;
}

