void ADFTypes::Fins::read(IO::File& buffer) {
    lift_vs_attack_angle_deg.read(buffer);
    max_steering_vs_speed_ms.read(buffer);
    reference_speed_ms = buffer.read_pod<float32>();
    pressure_drag = buffer.read_pod<float32>();
    pressure_drag2 = buffer.read_pod<float32>();
    buffer.skip(4);
    for(int i = 0; i < 5; ++i) {
        fins[i].read(buffer);
    }
    number_of_fins = buffer.read_pod<uint8>();
    buffer.skip(7);
}

void ADFTypes::Fins::print(std::ostream &out) const {
    lift_vs_attack_angle_deg.print(out);
    max_steering_vs_speed_ms.print(out);
    out << "reference_speed_ms: " << reference_speed_ms << "\n";
    out << "pressure_drag: " << pressure_drag << "\n";
    out << "pressure_drag2: " << pressure_drag2 << "\n";
    out << "fins: \n";
    fins.print(out);
    out << "\n";
    out << "number_of_fins: " << number_of_fins << "\n";
}

nlohmann::json ADFTypes::Fins::to_json() const {
    nlohmann::json _res;
    _res["lift_vs_attack_angle_deg"] = lift_vs_attack_angle_deg.to_json();
    _res["max_steering_vs_speed_ms"] = max_steering_vs_speed_ms.to_json();
    _res["reference_speed_ms"] = reference_speed_ms;
    _res["pressure_drag"] = pressure_drag;
    _res["pressure_drag2"] = pressure_drag2;
    _res["fins"] = fins.to_json();
    _res["number_of_fins"] = number_of_fins;
    return _res;
}

