void ADFTypes::Rudder::read(IO::File& buffer) {
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    physics_component_name.read(buffer);
    for(int i = 0; i < 3; ++i) {
        hinge_point[i] = buffer.read_pod<float32>();
    }
    hinge_angles.read(buffer);
    zero_angle_deg_vs_speed_kph.read(buffer);
    distance_to_hinge = buffer.read_pod<float32>();
    turn_steering_factor = buffer.read_pod<float32>();
    pitch_steering_factor = buffer.read_pod<float32>();
    roll_steering_factor = buffer.read_pod<float32>();
    min_angle_deg = buffer.read_pod<float32>();
    max_angle_deg = buffer.read_pod<float32>();
    air_density = buffer.read_pod<float32>();
    frontal_area = buffer.read_pod<float32>();
    drag_coefficient = buffer.read_pod<float32>();
    lift_coefficient = buffer.read_pod<float32>();
    buffer.skip(4);
}

void ADFTypes::Rudder::print(std::ostream &out) const {
    out << "name: " << name << "\n";
    physics_component_name.print(out);
    out << "hinge_point: \n";
    hinge_point.print(out);
    out << "\n";
    hinge_angles.print(out);
    zero_angle_deg_vs_speed_kph.print(out);
    out << "distance_to_hinge: " << distance_to_hinge << "\n";
    out << "turn_steering_factor: " << turn_steering_factor << "\n";
    out << "pitch_steering_factor: " << pitch_steering_factor << "\n";
    out << "roll_steering_factor: " << roll_steering_factor << "\n";
    out << "min_angle_deg: " << min_angle_deg << "\n";
    out << "max_angle_deg: " << max_angle_deg << "\n";
    out << "air_density: " << air_density << "\n";
    out << "frontal_area: " << frontal_area << "\n";
    out << "drag_coefficient: " << drag_coefficient << "\n";
    out << "lift_coefficient: " << lift_coefficient << "\n";
}

nlohmann::json ADFTypes::Rudder::to_json() const {
    nlohmann::json _res;
    _res["name"] = name;
    _res["physics_component_name"] = physics_component_name.to_json();
    _res["hinge_point"] = hinge_point.to_json();
    _res["hinge_angles"] = hinge_angles.to_json();
    _res["zero_angle_deg_vs_speed_kph"] = zero_angle_deg_vs_speed_kph.to_json();
    _res["distance_to_hinge"] = distance_to_hinge;
    _res["turn_steering_factor"] = turn_steering_factor;
    _res["pitch_steering_factor"] = pitch_steering_factor;
    _res["roll_steering_factor"] = roll_steering_factor;
    _res["min_angle_deg"] = min_angle_deg;
    _res["max_angle_deg"] = max_angle_deg;
    _res["air_density"] = air_density;
    _res["frontal_area"] = frontal_area;
    _res["drag_coefficient"] = drag_coefficient;
    _res["lift_coefficient"] = lift_coefficient;
    return _res;
}

