void ADFTypes::CChainObjectData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    connection_height = buffer.read_pod<float32>();
    buffer.skip(4);
    _control_point_surface_normal.read(buffer);
    attach_to_physics = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        _spline_end_pos[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 16; ++i) {
        _spline_start_pos[i] = buffer.read_pod<float32>();
    }
    distance_between = buffer.read_pod<float32>();
    spline.read(buffer);
}

