void ADFTypes::CVegetationSoundData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        hooked_model_hash = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    closest_zone_distance_allowed = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    world_audio_loop_volume_dampening = buffer.read_pod<float32>();
    enabled = buffer.read_pod<int32>();
    min_emitter_retrigger_time = buffer.read_pod<float32>();
    max_audible_emitters_xbone = buffer.read_pod<int32>();
    max_emitter_retrigger_time = buffer.read_pod<float32>();
    hooked_model_height_percentage = buffer.read_pod<float32>();
    _exportable = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    max_audible_emitters_ps4 = buffer.read_pod<int32>();
    min_emitter_to_emitter_distance = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        hooked_model_base_path = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    max_audible_emitters = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::CVegetationSoundData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "hooked_model_hash: " << hooked_model_hash << "\n";
    out << "closest_zone_distance_allowed: " << closest_zone_distance_allowed << "\n";
    out << "name: " << name << "\n";
    out << "world_audio_loop_volume_dampening: " << world_audio_loop_volume_dampening << "\n";
    out << "enabled: " << enabled << "\n";
    out << "min_emitter_retrigger_time: " << min_emitter_retrigger_time << "\n";
    out << "max_audible_emitters_xbone: " << max_audible_emitters_xbone << "\n";
    out << "max_emitter_retrigger_time: " << max_emitter_retrigger_time << "\n";
    out << "hooked_model_height_percentage: " << hooked_model_height_percentage << "\n";
    out << "_exportable: " << _exportable << "\n";
    out << "world: \n";
    world.print(out);
    out << "\n";
    out << "max_audible_emitters_ps4: " << max_audible_emitters_ps4 << "\n";
    out << "min_emitter_to_emitter_distance: " << min_emitter_to_emitter_distance << "\n";
    out << "hooked_model_base_path: " << hooked_model_base_path << "\n";
    out << "max_audible_emitters: " << max_audible_emitters << "\n";
}

nlohmann::json ADFTypes::CVegetationSoundData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["hooked_model_hash"] = hooked_model_hash;
    _res["closest_zone_distance_allowed"] = closest_zone_distance_allowed;
    _res["name"] = name;
    _res["world_audio_loop_volume_dampening"] = world_audio_loop_volume_dampening;
    _res["enabled"] = enabled;
    _res["min_emitter_retrigger_time"] = min_emitter_retrigger_time;
    _res["max_audible_emitters_xbone"] = max_audible_emitters_xbone;
    _res["max_emitter_retrigger_time"] = max_emitter_retrigger_time;
    _res["hooked_model_height_percentage"] = hooked_model_height_percentage;
    _res["_exportable"] = _exportable;
    _res["world"] = world.to_json();
    _res["max_audible_emitters_ps4"] = max_audible_emitters_ps4;
    _res["min_emitter_to_emitter_distance"] = min_emitter_to_emitter_distance;
    _res["hooked_model_base_path"] = hooked_model_base_path;
    _res["max_audible_emitters"] = max_audible_emitters;
    return _res;
}

