void ADFTypes::VehicleDamage::read(IO::File& buffer) {
    max_health = buffer.read_pod<int32>();
    bullet_armor = buffer.read_pod<int32>();
    bullet_armor_strength = buffer.read_pod<float32>();
    bullet_heavy_armor = buffer.read_pod<int32>();
    bullet_heavy_armor_strength = buffer.read_pod<float32>();
    explosion_armor = buffer.read_pod<int32>();
    explosion_armor_strength = buffer.read_pod<float32>();
    impact_armor = buffer.read_pod<int32>();
    impact_armor_strength = buffer.read_pod<float32>();
    fire_armor = buffer.read_pod<int32>();
    fire_armor_strength = buffer.read_pod<float32>();
    melee_armor = buffer.read_pod<int32>();
    melee_armor_strength = buffer.read_pod<float32>();
    electricity_armor = buffer.read_pod<int32>();
    electricity_armor_strength = buffer.read_pod<float32>();
    grapple_pull_armor = buffer.read_pod<int32>();
    grapple_pull_armor_strength = buffer.read_pod<float32>();
    impact_damage_factor = buffer.read_pod<float32>();
    deform_scale = buffer.read_pod<float32>();
    damaged_threshold = buffer.read_pod<float32>();
    block_parts_damage_use_threshold = buffer.read_pod<int8>();
    buffer.skip(1);
    block_parts_damage_health_threshold = buffer.read_pod<int16>();
    explosion_delay_s = buffer.read_pod<uint16>();
    burn_duration_s = buffer.read_pod<uint16>();
    vulnerable_duration_s = buffer.read_pod<uint16>();
    buffer.skip(2);
    explosion_threshold = buffer.read_pod<int32>();
    npc_explosion_threshold = buffer.read_pod<int32>();
    vulnerable_explosion_threshold = buffer.read_pod<int32>();
    impact_deform_threshold = buffer.read_pod<int32>();
    weapon_deform_threshold = buffer.read_pod<int32>();
    low_health_threshold = buffer.read_pod<float32>();
    safe_mode.read(buffer);
    buffer.skip(4);
    part_damage_types.read(buffer);
    environment_ramming_damage_mass_constant = buffer.read_pod<float32>();
    buffer.skip(4);
}

