void ADFTypes::CCombatantWaveData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    combatantwaverule.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    OnCompleted.read(buffer);
    delay_before_next_wave = buffer.read_pod<float32>();
    buffer.skip(4);
    OnActivated.read(buffer);
    order = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::CCombatantWaveData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    combatantwaverule.print(out);
    out << "name: " << name << "\n";
    OnCompleted.print(out);
    out << "delay_before_next_wave: " << delay_before_next_wave << "\n";
    OnActivated.print(out);
    out << "order: " << order << "\n";
}

nlohmann::json ADFTypes::CCombatantWaveData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["combatantwaverule"] = combatantwaverule.to_json();
    _res["name"] = name;
    _res["OnCompleted"] = OnCompleted.to_json();
    _res["delay_before_next_wave"] = delay_before_next_wave;
    _res["OnActivated"] = OnActivated.to_json();
    _res["order"] = order;
    return _res;
}

