void ADFTypes::SIntentConditionSoundModuleControllerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        operand1 = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        operand2 = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    operand2_type = buffer.read_pod<int32>();
    value_type = buffer.read_pod<int32>();
    _exportable = buffer.read_pod<int32>();
    operation = buffer.read_pod<int32>();
    operand1_type = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        sound_module_query_function = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::SIntentConditionSoundModuleControllerData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "operand1: " << operand1 << "\n";
    out << "name: " << name << "\n";
    out << "operand2: " << operand2 << "\n";
    out << "operand2_type: " << operand2_type << "\n";
    out << "value_type: " << value_type << "\n";
    out << "_exportable: " << _exportable << "\n";
    out << "operation: " << operation << "\n";
    out << "operand1_type: " << operand1_type << "\n";
    out << "sound_module_query_function: " << sound_module_query_function << "\n";
}

nlohmann::json ADFTypes::SIntentConditionSoundModuleControllerData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["operand1"] = operand1;
    _res["name"] = name;
    _res["operand2"] = operand2;
    _res["operand2_type"] = operand2_type;
    _res["value_type"] = value_type;
    _res["_exportable"] = _exportable;
    _res["operation"] = operation;
    _res["operand1_type"] = operand1_type;
    _res["sound_module_query_function"] = sound_module_query_function;
    return _res;
}

