void ADFTypes::CImpulseData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    for(int i = 0; i < 3; ++i) {
        random_direction_offset[i] = buffer.read_pod<float32>();
    }
    override_current_velocity = buffer.read_pod<int32>();
    blackboard_alias.read(buffer);
    arc_towards_player = buffer.read_pod<int32>();
    random_angular_speed_min = buffer.read_pod<float32>();
    max_linear_speed = buffer.read_pod<float32>();
    launch_at_player = buffer.read_pod<int32>();
    pick_reference_object.read(buffer);
    enable.read(buffer);
    use_random_direction = buffer.read_pod<int32>();
    buffer.skip(4);
    disable.read(buffer);
    launch_on_enable = buffer.read_pod<int32>();
    random_angular_speed_max = buffer.read_pod<float32>();
    use_local_space_for_random_direction_offset = buffer.read_pod<int32>();
    blackboard_target_key = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    launch.read(buffer);
    linear_speed = buffer.read_pod<float32>();
    enabled = buffer.read_pod<int32>();
    linear_speed_randomness = buffer.read_pod<float32>();
    arc_target_offset_distance = buffer.read_pod<float32>();
    blackboard_use_arc = buffer.read_pod<int32>();
    arc_time_to_impact = buffer.read_pod<float32>();
}

