void ADFTypes::GeneralR2Constants::read(IO::File& buffer) {
    DepthBias = buffer.read_pod<float32>();
    DetailRepeatU = buffer.read_pod<float32>();
    DetailRepeatV = buffer.read_pod<float32>();
    TerrainColorFactor = buffer.read_pod<float32>();
    TerrainTopProjection = buffer.read_pod<float32>();
    BlendMaskContrast1 = buffer.read_pod<float32>();
    BlendMaskContrast2 = buffer.read_pod<float32>();
    BlendUVMultiplier1 = buffer.read_pod<float32>();
    BlendUVMultiplier2 = buffer.read_pod<float32>();
    BlendMaskBias1 = buffer.read_pod<float32>();
    BlendMaskBias2 = buffer.read_pod<float32>();
    BlendMaskBreakup1 = buffer.read_pod<float32>();
    BlendMaskBreakup2 = buffer.read_pod<float32>();
    EmissiveScale = buffer.read_pod<float32>();
    EmissiveExposureAdapt = buffer.read_pod<float32>();
    EmissiveRollOff = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        TintColor1[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        TintColor2[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        TintColor3[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        TintColor4[i] = buffer.read_pod<float32>();
    }
    TintBreakup = buffer.read_pod<float32>();
    TintContrast = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        DecalAlphaWeights[i] = buffer.read_pod<float32>();
    }
    DirtUVMultiplier = buffer.read_pod<float32>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        ObjectSpaceNormal = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        UseEmissive = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        EmissiveOnlyTransparent = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        EmissiveTextureHasColor = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        UseEmissiveLightColor = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        DoubleSided = (bitfield_value >> 5) & ((1ULL << 1) - 1);
        DecalBlend = (bitfield_value >> 6) & ((1ULL << 1) - 1);
        AlphaTest = (bitfield_value >> 7) & ((1ULL << 1) - 1);
        DetailUV2 = (bitfield_value >> 8) & ((1ULL << 1) - 1);
        UseAlbedoDetail = (bitfield_value >> 9) & ((1ULL << 1) - 1);
        AlbedoDetailAlphaGloss = (bitfield_value >> 10) & ((1ULL << 1) - 1);
        UseNormalDetail = (bitfield_value >> 11) & ((1ULL << 1) - 1);
    }
    UseTint = buffer.read_pod<float32>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        TintUV2 = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    TintOrder = buffer.read_pod<float32>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        UseTextureBlend1 = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        AnimateTexture = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        UseVertexAnimations = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        UseRigidVertexAnimations = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        UseSoftVertexAnimations = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        UseFluidVertexAnimations = (bitfield_value >> 5) & ((1ULL << 1) - 1);
    }
    VertexAnimBBoxMin = buffer.read_pod<float32>();
    VertexAnimBBoxMax = buffer.read_pod<float32>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        VertexAnimSwizzle = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    VertexAnimPhase = buffer.read_pod<float32>();
    VertexAnimFrames = buffer.read_pod<uint32>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        VertexAnimLoops = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        Directional = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        Fur = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        HDRRef = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        UseTextureBlend2 = (bitfield_value >> 4) & ((1ULL << 1) - 1);
    }
    DirtEnabled = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        DirtColor[i] = buffer.read_pod<float32>();
    }
    DirtAmount = buffer.read_pod<float32>();
    DirtRoughness = buffer.read_pod<float32>();
    DirtBias = buffer.read_pod<float32>();
    DirtBreakup = buffer.read_pod<float32>();
    DirtContrast = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        DebugColor[i] = buffer.read_pod<float32>();
    }
}

