void ADFTypes::SArmorDecayStageData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    for(int i = 0; i < 3; ++i) {
        player_rel_vel_min[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        angular_vel_min[i] = buffer.read_pod<float32>();
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        decay_effect_usage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    decay_event.read(buffer);
    rigid_object_ref.read(buffer);
    for(int i = 0; i < 3; ++i) {
        angular_vel_max[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        local_spawn_vel_min[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        local_spawn_vel_max[i] = buffer.read_pod<float32>();
    }
    decay_threshold = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        player_rel_vel_max[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
}

