void ADFTypes::CharacterSkinConstants::read(IO::File& buffer) {
    TransmissionModulator = buffer.read_pod<float32>();
    EmissiveScale = buffer.read_pod<float32>();
    CameraStrength = buffer.read_pod<float32>();
    CameraSpecular = buffer.read_pod<float32>();
    DirtFactor = buffer.read_pod<float32>();
    FurLength = buffer.read_pod<float32>();
    FurThickness = buffer.read_pod<float32>();
    FurRoughness = buffer.read_pod<float32>();
    FurGravity = buffer.read_pod<float32>();
    FurSize = buffer.read_pod<float32>();
    GibAlbedoUVScale = buffer.read_pod<float32>();
    GibDetailUVScale = buffer.read_pod<float32>();
    GibSpecGloss = buffer.read_pod<float32>();
    GibSoftDetailEdge = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        TintColor1[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        TintColor2[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        TintColor3[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        TintColor4[i] = buffer.read_pod<float32>();
    }
    DetailUVmult1 = buffer.read_pod<float32>();
    DetailUVmult2 = buffer.read_pod<float32>();
    DetailUVmult3 = buffer.read_pod<float32>();
    DetailUVmult4 = buffer.read_pod<float32>();
    BlendUVMultiplier1 = buffer.read_pod<float32>();
    BlendMaskBias1 = buffer.read_pod<float32>();
    BlendMaskBreakup1 = buffer.read_pod<float32>();
    BlendMaskContrast1 = buffer.read_pod<float32>();
    WrinkleStrength = buffer.read_pod<float32>();
    WrinkleOffsetBrowLeft = buffer.read_pod<float32>();
    WrinkleOffsetBrowMid = buffer.read_pod<float32>();
    WrinkleOffsetBrowRight = buffer.read_pod<float32>();
    WrinkleOffsetUpcheekLeft = buffer.read_pod<float32>();
    WrinkleOffsetNoseLeft = buffer.read_pod<float32>();
    WrinkleOffsetNoseRight = buffer.read_pod<float32>();
    WrinkleOffsetUpcheekRight = buffer.read_pod<float32>();
    WrinkleOffsetJawLeft = buffer.read_pod<float32>();
    WrinkleOffsetMouthbottomLeft = buffer.read_pod<float32>();
    WrinkleOffsetMouthbottomRight = buffer.read_pod<float32>();
    WrinkleOffsetJawRight = buffer.read_pod<float32>();
    WrinkleOffsetNeckStretchLeft = buffer.read_pod<float32>();
    WrinkleOffsetNeckStretchRight = buffer.read_pod<float32>();
    WrinkleOffsetJawDownLeft = buffer.read_pod<float32>();
    WrinkleOffsetJawDownRight = buffer.read_pod<float32>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        BlendUseUV2 = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        UseTint = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        DoubleSided = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        UseAlphaMask = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        UseWrinkleMap = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        UseFur = (bitfield_value >> 5) & ((1ULL << 1) - 1);
        UseGibAlbedo = (bitfield_value >> 6) & ((1ULL << 1) - 1);
        UseGibDetail = (bitfield_value >> 7) & ((1ULL << 1) - 1);
        TriangleAdjacency = (bitfield_value >> 8) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

