void ADFTypes::SAnimTextureRandomData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    Width = buffer.read_pod<int32>();
    Frequency = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Height = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::SAnimTextureRandomData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "Width: " << Width << "\n";
    out << "Frequency: " << Frequency << "\n";
    out << "name: " << name << "\n";
    out << "Height: " << Height << "\n";
}

nlohmann::json ADFTypes::SAnimTextureRandomData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["Width"] = Width;
    _res["Frequency"] = Frequency;
    _res["name"] = name;
    _res["Height"] = Height;
    return _res;
}

