void ADFTypes::SAttachedEffectParamData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    FirstFrameOnly = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        Parameter = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        Routing = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::SAttachedEffectParamData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "FirstFrameOnly: " << FirstFrameOnly << "\n";
    out << "Parameter: " << Parameter << "\n";
    out << "name: " << name << "\n";
    out << "Routing: " << Routing << "\n";
}

nlohmann::json ADFTypes::SAttachedEffectParamData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["FirstFrameOnly"] = FirstFrameOnly;
    _res["Parameter"] = Parameter;
    _res["name"] = name;
    _res["Routing"] = Routing;
    return _res;
}

