void ADFTypes::CForcePulseData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    cone_angle = buffer.read_pod<float32>();
    buffer.skip(4);
    sendmatrix.read(buffer);
    explosion_hit_pos_to_COM_scaler = buffer.read_pod<float32>();
    enable_by_default = buffer.read_pod<int32>();
    impact_scale_at_max_radius = buffer.read_pod<float32>();
    exclude_player_force = buffer.read_pod<int32>();
    exclude_damager = buffer.read_pod<int32>();
    radius = buffer.read_pod<float32>();
    base_shatter = buffer.read_pod<float32>();
    buffer.skip(4);
    in_air_explosion_sound.read(buffer);
    explosion_velocity = buffer.read_pod<float32>();
    base_gib = buffer.read_pod<float32>();
    base_stagger = buffer.read_pod<float32>();
    max_pressure_radius = buffer.read_pod<float32>();
    explosion_hit_pos_to_COM_random_size = buffer.read_pod<float32>();
    buffer.skip(4);
    bullet_spawner_ref.read(buffer);
    radius_fraction_for_min_gib = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        Spell = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    cone_target_ref.read(buffer);
    destruction_damage = buffer.read_pod<float32>();
    buffer.skip(4);
    explode_event.read(buffer);
    explosion_use_center_of_mass_on_vehicles = buffer.read_pod<int32>();
    do_cone_damage = buffer.read_pod<int32>();
    explosion_direction_vertical_multiplier = buffer.read_pod<float32>();
    gib_scale_at_max_radius = buffer.read_pod<float32>();
    faction_override = buffer.read_pod<int32>();
    buffer.skip(4);
    explosion_effect_table.read(buffer);
    move_to_player_on_active = buffer.read_pod<int32>();
    explosion_normal_always_up = buffer.read_pod<int32>();
    despawn_radius = buffer.read_pod<float32>();
    exclude_character_force = buffer.read_pod<int32>();
    on_explode_event.read(buffer);
    skip_spell_damage_params = buffer.read_pod<int32>();
    explosion_does_tumble_damage = buffer.read_pod<int32>();
    exclude_character_damage = buffer.read_pod<int32>();
    in_air_explosion_effect = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        explosion_center_offset[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    damager_weapon_ref.read(buffer);
    radius_fraction_for_max_impact = buffer.read_pod<float32>();
    knock_up_speed = buffer.read_pod<float32>();
    friendly_fire_multiplier = buffer.read_pod<float32>();
    exclude_camera_shakes = buffer.read_pod<int32>();
    tumble_velocity_min_up = buffer.read_pod<float32>();
    explosion_direction_override_factor = buffer.read_pod<float32>();
    can_fullbody_gib = buffer.read_pod<int32>();
    explosion_does_nano_float = buffer.read_pod<int32>();
    sound_module_preset_for_explosion = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    explosion_buff_name = buffer.read_pod<int32>();
    buffer.skip(4);
    receive_matrix_event.read(buffer);
    knock_back_speed = buffer.read_pod<float32>();
    explosion_pressure = buffer.read_pod<float32>();
    explosion_from_player_cannot_damage_player_vehicle = buffer.read_pod<int32>();
    explosion_velocity_min = buffer.read_pod<float32>();
    explosion_does_force_kill = buffer.read_pod<int32>();
    buffer.skip(4);
    damager_owner_ref.read(buffer);
    tumble_velocity = buffer.read_pod<float32>();
    buffer.skip(4);
    disableonevent.read(buffer);
    for(int i = 0; i < 3; ++i) {
        explosion_direction_override[i] = buffer.read_pod<float32>();
    }
    explosion_pressure_min = buffer.read_pod<float32>();
    enableonevent.read(buffer);
    explosion_direction_horizontal_multiplier = buffer.read_pod<float32>();
    base_damage = buffer.read_pod<int32>();
    exclude_player_damage = buffer.read_pod<int32>();
    extra_reaction_radius = buffer.read_pod<float32>();
    explosion_force_direction_noise_angle = buffer.read_pod<float32>();
    radius_fraction_for_min_impact = buffer.read_pod<float32>();
    use_faction_override = buffer.read_pod<int32>();
    intended_target_is_player = buffer.read_pod<int32>();
    radius_fraction_for_max_gib = buffer.read_pod<float32>();
    buffer.skip(4);
    damager_ref.read(buffer);
    SettingsFile = buffer.read_pod<int32>();
    buffer.skip(4);
}

