void ADFTypes::CUpgradeSlamStrengthData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    max_damage_multiplier = buffer.read_pod<float32>();
    min_damage_multiplier = buffer.read_pod<float32>();
    min_stagger_multiplier = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    max_stagger_multiplier = buffer.read_pod<float32>();
    buffer.skip(4);
}

