void ADFTypes::SSoundModuleControllerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        module_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        preset_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        type_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        preset_arg = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _exportable = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::SSoundModuleControllerData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "module_name: " << module_name << "\n";
    out << "preset_name: " << preset_name << "\n";
    out << "type_name: " << type_name << "\n";
    out << "preset_arg: " << preset_arg << "\n";
    out << "_exportable: " << _exportable << "\n";
}

nlohmann::json ADFTypes::SSoundModuleControllerData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["module_name"] = module_name;
    _res["preset_name"] = preset_name;
    _res["type_name"] = type_name;
    _res["preset_arg"] = preset_arg;
    _res["_exportable"] = _exportable;
    return _res;
}

static std::unique_ptr<ADFTypes::SSoundModuleControllerData> SSoundModuleControllerData_new_instance() {
    return std::make_unique<ADFTypes::SSoundModuleControllerData>();
}

void ADFTypes::CImpactDampenerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    on_impact.read(buffer);
    enable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<int32>();
    threshold_acceleration = buffer.read_pod<float32>();
    dampening_percent = buffer.read_pod<float32>();
    buffer.skip(4);
    disable.read(buffer);
    max_speed = buffer.read_pod<float32>();
    buffer.skip(4);
}

