    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["on_impact"] = on_impact.to_json();
    _res["enable"] = enable.to_json();
    _res["name"] = name;
    _res["enabled"] = enabled;
    _res["threshold_acceleration"] = threshold_acceleration;
    _res["dampening_percent"] = dampening_percent;
    _res["disable"] = disable.to_json();
    _res["max_speed"] = max_speed;
    return _res;
