void ADFTypes::BountyPoint::read(IO::File& buffer) {
    BountyId = buffer.read_pod<uint32>();
    MissionId = buffer.read_pod<uint32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        BountyIdText = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Factions = buffer.read_pod<uint32>();
    RewardPackageType = buffer.read_pod<uint32>();
    StartEnabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 3; ++i) {
        Position[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 10; ++i) {
        BountyTags[i] = buffer.read_pod<uint32>();
    }
    EnableEvent.read(buffer);
    DisableEvent.read(buffer);
}

