void ADFTypes::_locationData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    global_load_order = buffer.read_pod<int32>();
    far_load_distance = buffer.read_pod<float32>();
    on_load_event.read(buffer);
    global_persistence = buffer.read_pod<int32>();
    buffer.skip(4);
    enable_event.read(buffer);
    unload_event.read(buffer);
    exclude_from_navmesh = buffer.read_pod<int32>();
    buffer.skip(4);
    load_event.read(buffer);
    enabled = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        transform[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        mission = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        dependency = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    sync_near_and_far_loading = buffer.read_pod<int32>();
    add_referenced_fmod_banks = buffer.read_pod<int32>();
    distance_unload_event.read(buffer);
    on_unload_event.read(buffer);
    reload_event.read(buffer);
    near_load_distance = buffer.read_pod<float32>();
    buffer.skip(4);
    disable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        location_type = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

