void ADFTypes::VehicleDestroyed::read(IO::File& buffer) {
    X = buffer.read_pod<float32>();
    Y = buffer.read_pod<float32>();
    Z = buffer.read_pod<float32>();
    Faction = buffer.read_pod<int32>();
    Type = buffer.read_pod<int32>();
    NumSeats = buffer.read_pod<uint32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        EverHadOccupants = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        DestroyedByVehicle = (bitfield_value >> 1) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
    DestroyerVehicleType = buffer.read_pod<int32>();
    Weapon = buffer.read_pod<uint32>();
    Location = buffer.read_pod<uint32>();
    Region = buffer.read_pod<uint32>();
    NameHash = buffer.read_pod<uint32>();
}

