void ADFTypes::CFadeScreenData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    fade_in_time = buffer.read_pod<float32>();
    buffer.skip(4);
    enable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    fade_out_time = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        image = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    fade_in_event.read(buffer);
    disable.read(buffer);
    fade_alpha = buffer.read_pod<float32>();
    buffer.skip(4);
    fade_out_event.read(buffer);
    fade_over_menus = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::CFadeScreenData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "fade_in_time: " << fade_in_time << "\n";
    enable.print(out);
    out << "name: " << name << "\n";
    out << "fade_out_time: " << fade_out_time << "\n";
    out << "image: " << image << "\n";
    fade_in_event.print(out);
    disable.print(out);
    out << "fade_alpha: " << fade_alpha << "\n";
    fade_out_event.print(out);
    out << "fade_over_menus: " << fade_over_menus << "\n";
}

nlohmann::json ADFTypes::CFadeScreenData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["fade_in_time"] = fade_in_time;
    _res["enable"] = enable.to_json();
    _res["name"] = name;
    _res["fade_out_time"] = fade_out_time;
    _res["image"] = image;
    _res["fade_in_event"] = fade_in_event.to_json();
    _res["disable"] = disable.to_json();
    _res["fade_alpha"] = fade_alpha;
    _res["fade_out_event"] = fade_out_event.to_json();
    _res["fade_over_menus"] = fade_over_menus;
    return _res;
}

