void ADFTypes::Spline10::read(IO::File& buffer) {
    x_min = buffer.read_pod<float32>();
    x_max = buffer.read_pod<float32>();
    y_min = buffer.read_pod<float32>();
    y_max = buffer.read_pod<float32>();
    number_of_control_points = buffer.read_pod<int8>();
    buffer.skip(3);
    for(int i = 0; i < 10; ++i) {
        control_points[i].read(buffer);
    }
}

void ADFTypes::Spline10::print(std::ostream &out) const {
    out << "x_min: " << x_min << "\n";
    out << "x_max: " << x_max << "\n";
    out << "y_min: " << y_min << "\n";
    out << "y_max: " << y_max << "\n";
    out << "number_of_control_points: " << number_of_control_points << "\n";
    out << "control_points: \n";
    control_points.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::Spline10::to_json() const {
    nlohmann::json _res;
    _res["x_min"] = x_min;
    _res["x_max"] = x_max;
    _res["y_min"] = y_min;
    _res["y_max"] = y_max;
    _res["number_of_control_points"] = number_of_control_points;
    _res["control_points"] = control_points.to_json();
    return _res;
}

