void ADFTypes::RestartPoint::read(IO::File& buffer) {
    OnLoadEvent.read(buffer);
    GlobalEnableEvent.read(buffer);
    GlobalDisableEvent.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ID = buffer.read_pod<uint64>();
    NameId = buffer.read_pod<uint32>();
    for(int i = 0; i < 12; ++i) {
        Transform[i] = buffer.read_pod<float32>();
    }
    LocationHash = buffer.read_pod<uint32>();
    Type = buffer.read_pod<uint8>();
    Enabled = buffer.read_pod<uint8>();
    PlayerPlacement = buffer.read_pod<uint8>();
    SaveOnEnabled = buffer.read_pod<uint8>();
    SaveOnDisabled = buffer.read_pod<uint8>();
    buffer.skip(3);
}

void ADFTypes::RestartPoint::print(std::ostream &out) const {
    out << "OnLoadEvent: \n";
    OnLoadEvent.print(out);
    out << "\n";
    out << "GlobalEnableEvent: \n";
    GlobalEnableEvent.print(out);
    out << "\n";
    out << "GlobalDisableEvent: \n";
    GlobalDisableEvent.print(out);
    out << "\n";
    out << "Name: " << Name << "\n";
    out << "ID: " << ID << "\n";
    out << "NameId: " << NameId << "\n";
    out << "Transform: \n";
    Transform.print(out);
    out << "\n";
    out << "LocationHash: " << LocationHash << "\n";
    out << "Type: " << Type << "\n";
    out << "Enabled: " << Enabled << "\n";
    out << "PlayerPlacement: " << PlayerPlacement << "\n";
    out << "SaveOnEnabled: " << SaveOnEnabled << "\n";
    out << "SaveOnDisabled: " << SaveOnDisabled << "\n";
}

nlohmann::json ADFTypes::RestartPoint::to_json() const {
    nlohmann::json _res;
    _res["OnLoadEvent"] = OnLoadEvent.to_json();
    _res["GlobalEnableEvent"] = GlobalEnableEvent.to_json();
    _res["GlobalDisableEvent"] = GlobalDisableEvent.to_json();
    _res["Name"] = Name;
    _res["ID"] = ID;
    _res["NameId"] = NameId;
    _res["Transform"] = Transform.to_json();
    _res["LocationHash"] = LocationHash;
    _res["Type"] = Type;
    _res["Enabled"] = Enabled;
    _res["PlayerPlacement"] = PlayerPlacement;
    _res["SaveOnEnabled"] = SaveOnEnabled;
    _res["SaveOnDisabled"] = SaveOnDisabled;
    return _res;
}

