void ADFTypes::AutoAimSettings::read(IO::File& buffer) {
    AngleThresholdNewTarget = buffer.read_pod<float32>();
    AngleThresholdCurrentTarget = buffer.read_pod<float32>();
    AngleThreshMultiplierAtCutoff = buffer.read_pod<float32>();
    AngleThreshMultiplierCutoff = buffer.read_pod<float32>();
    StickyAimStartAngle = buffer.read_pod<float32>();
    StickyAimAngleNewTarget = buffer.read_pod<float32>();
    StickyAimAngleCurrentTarget = buffer.read_pod<float32>();
    StickyAimStrength = buffer.read_pod<float32>();
    StickyAimMinAccValue = buffer.read_pod<float32>();
    StickyAimMaxAccValue = buffer.read_pod<float32>();
    SnapAimTarget = buffer.read_pod<float32>();
    FitWeightCurrentTarget = buffer.read_pod<float32>();
    FitWeightCurrentTargetNoInput = buffer.read_pod<float32>();
    FitWeightDistance = buffer.read_pod<float32>();
    FitWeightAngleDeflection = buffer.read_pod<float32>();
    AlwaysTargetDistance = buffer.read_pod<float32>();
    UseDirectWeaponTargeting = buffer.read_pod<uint32>();
    MaxAimDistance = buffer.read_pod<float32>();
    MinAimDistance = buffer.read_pod<float32>();
    MaxAimDistanceWithTarget = buffer.read_pod<float32>();
    CanTargetCharacters = buffer.read_pod<uint32>();
    CanTargetVehicles = buffer.read_pod<uint32>();
    CanTargetRigidObjects = buffer.read_pod<uint32>();
    CharacterTargetAngleScale = buffer.read_pod<float32>();
    PlayerWeaponAimSource = buffer.read_pod<uint32>();
    VerticalAssistAimSource = buffer.read_pod<uint32>();
    for(int i = 0; i < 3; ++i) {
        PlayerWeaponAimSourceOffset[i] = buffer.read_pod<float32>();
    }
    PlayerWeaponAimVerticalAdjustSpeed = buffer.read_pod<float32>();
    OutlineWeaponTarget = buffer.read_pod<uint32>();
}

