void ADFTypes::CCameraGlobalAttachmentModifierData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    ignore_x_offset = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    camera_attach_object.read(buffer);
    for(int i = 0; i < 16; ++i) {
        holder_offset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 16; ++i) {
        parent_transform[i] = buffer.read_pod<float32>();
    }
    bone_local_space_hysteresis_size = buffer.read_pod<int32>();
    use_root_orientation = buffer.read_pod<int32>();
    attachment_type = buffer.read_pod<int32>();
    world_y = buffer.read_pod<int32>();
}

