void ADFTypes::AdfModelCollectionInstance::read(IO::File& buffer) {
    for(int i = 0; i < 16; ++i) {
        Transform[i] = buffer.read_pod<float32>();
    }
    ModelIndex = buffer.read_pod<uint16>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        CastShadow = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        ClipOnDistance = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        SizeCull = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        SkyOccluder = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        SandAmount = (bitfield_value >> 4) & ((1ULL << 12) - 1);
    }
    for(int i = 0; i < 6; ++i) {
        AABB[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    EmissiveLightRefId = buffer.read_pod<uint64>();
}

void ADFTypes::AdfModelCollectionInstance::print(std::ostream &out) const {
    out << "Transform: \n";
    Transform.print(out);
    out << "\n";
    out << "ModelIndex: " << ModelIndex << "\n";
    out << "CastShadow: " << CastShadow << "\n";
    out << "ClipOnDistance: " << ClipOnDistance << "\n";
    out << "SizeCull: " << SizeCull << "\n";
    out << "SkyOccluder: " << SkyOccluder << "\n";
    out << "SandAmount: " << SandAmount << "\n";
    out << "AABB: \n";
    AABB.print(out);
    out << "\n";
    out << "EmissiveLightRefId: " << EmissiveLightRefId << "\n";
}

nlohmann::json ADFTypes::AdfModelCollectionInstance::to_json() const {
    nlohmann::json _res;
    _res["Transform"] = Transform.to_json();
    _res["ModelIndex"] = ModelIndex;
    _res["CastShadow"] = CastShadow;
    _res["ClipOnDistance"] = ClipOnDistance;
    _res["SizeCull"] = SizeCull;
    _res["SkyOccluder"] = SkyOccluder;
    _res["SandAmount"] = SandAmount;
    _res["AABB"] = AABB.to_json();
    _res["EmissiveLightRefId"] = EmissiveLightRefId;
    return _res;
}

static std::unique_ptr<ADFTypes::AdfModelCollectionInstance> AdfModelCollectionInstance_new_instance() {
    return std::make_unique<ADFTypes::AdfModelCollectionInstance>();
}

