void ADFTypes::TerrainMesh::read(IO::File& buffer) {
    for(int i = 0; i < 6; ++i) {
        BoundingBox[i] = buffer.read_pod<float32>();
    }
    Indices.read(buffer);
    IndexTypeSize = buffer.read_pod<uint32>();
    buffer.skip(4);
    Vertices.read(buffer);
    Vertices2.read(buffer);
    QuadInfos.read(buffer);
    TriangleIndices.read(buffer);
    GroupTriIndices.read(buffer);
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        QuadBasePrimitives = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(4);
}

void ADFTypes::TerrainMesh::print(std::ostream &out) const {
    out << "BoundingBox: \n";
    BoundingBox.print(out);
    out << "\n";
    Indices.print(out);
    out << "IndexTypeSize: " << IndexTypeSize << "\n";
    Vertices.print(out);
    Vertices2.print(out);
    QuadInfos.print(out);
    TriangleIndices.print(out);
    GroupTriIndices.print(out);
    out << "QuadBasePrimitives: " << QuadBasePrimitives << "\n";
}

nlohmann::json ADFTypes::TerrainMesh::to_json() const {
    nlohmann::json _res;
    _res["BoundingBox"] = BoundingBox.to_json();
    _res["Indices"] = Indices.to_json();
    _res["IndexTypeSize"] = IndexTypeSize;
    _res["Vertices"] = Vertices.to_json();
    _res["Vertices2"] = Vertices2.to_json();
    _res["QuadInfos"] = QuadInfos.to_json();
    _res["TriangleIndices"] = TriangleIndices.to_json();
    _res["GroupTriIndices"] = GroupTriIndices.to_json();
    _res["QuadBasePrimitives"] = QuadBasePrimitives;
    return _res;
}

