void ADFTypes::CImplosionData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    on_implosion_done_event.read(buffer);
    do_finishing_impulse = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ignore_angle_for_rising_event.read(buffer);
    use_static_position_event.read(buffer);
    on_implosion_launch_character_event.read(buffer);
    ignore_player = buffer.read_pod<int32>();
    buffer.skip(4);
    implode_event.read(buffer);
    damage_type = buffer.read_pod<int32>();
    faction = buffer.read_pod<int32>();
    ignore_parent = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        settings_file = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    finish_implosion_event.read(buffer);
    on_implode_event.read(buffer);
}

