void ADFTypes::CInteractionGraphEntryData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    user_type = buffer.read_pod<int32>();
    use_tag = buffer.read_pod<int32>();
    validation_reference = buffer.read_pod<int32>();
    act_event = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        alignment_bone = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    action_identifier = buffer.read_pod<int32>();
    buffer.skip(4);
    entry_tags.read(buffer);
    state = buffer.read_pod<int32>();
    buffer.skip(4);
    display_name_ref.read(buffer);
    entry_position_obstruction = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    entry_position_projection = buffer.read_pod<int32>();
    interaction.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    entry_node.read(buffer);
    target_identifier = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        modifier = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

