void ADFTypes::CIntelActivatorData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        intel_tag = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    reinspectable = buffer.read_pod<int32>();
    buffer.skip(4);
    on_activated_intel_invalid.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_spawned_intel_invalid.read(buffer);
    activation_type = buffer.read_pod<int32>();
    buffer.skip(4);
    on_spawned_intel_valid.read(buffer);
    on_spawned_intel_already_activated.read(buffer);
    on_intel_invalidated.read(buffer);
    save = buffer.read_pod<int32>();
    buffer.skip(4);
    activate_event.read(buffer);
    on_activated_intel_valid.read(buffer);
}

