void ADFTypes::CLaserLineData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    manual_control = buffer.read_pod<int32>();
    strength = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        end[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 4; ++i) {
        color[i] = buffer.read_pod<float32>();
    }
    HideEvent.read(buffer);
    for(int i = 0; i < 3; ++i) {
        start[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    ShowEvent.read(buffer);
    OnHitEvent.read(buffer);
}

