void ADFTypes::Propeller::read(IO::File& buffer) {
    physics_component_name.read(buffer);
    for(int i = 0; i < 3; ++i) {
        hinge_position[i] = buffer.read_pod<float32>();
    }
    hinge_angles.read(buffer);
    trim_flattening_in_turns = buffer.read_pod<float32>();
    distance_to_hinge = buffer.read_pod<float32>();
    min_angle_deg = buffer.read_pod<float32>();
    max_angle_deg = buffer.read_pod<float32>();
    docking_limits.read(buffer);
    zero_angle_deg = buffer.read_pod<float32>();
    is_impeller = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 3; ++i) {
        impeller_intake_position[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
}

