void ADFTypes::CTeleportData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    fade_in_time = buffer.read_pod<float32>();
    credits_during_loading_screen = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    fade_out_time = buffer.read_pod<float32>();
    buffer.skip(4);
    disableonevent.read(buffer);
    enabled = buffer.read_pod<int32>();
    use_fade = buffer.read_pod<int32>();
    enableonevent.read(buffer);
    loading_screen = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        state = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    teleporting_object_alias.read(buffer);
    leave_player_disabled = buffer.read_pod<int32>();
    ignore_fade = buffer.read_pod<int32>();
    teleportonevent.read(buffer);
    teleportdonemsg.read(buffer);
    teleportmsg.read(buffer);
}

