void ADFTypes::CLaserBeamWeaponComponentData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    render_beam_fade_factor = buffer.read_pod<float32>();
    render_beam_emissive = buffer.read_pod<float32>();
    can_set_end_position_during_barrel_fire_direction = buffer.read_pod<int32>();
    laser_end_point_light = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    stop_raycast_on_end_position = buffer.read_pod<int32>();
    laser_end_point_light_falloff_start = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        LaserBeamColor[i] = buffer.read_pod<float32>();
    }
    delay_after_firing = buffer.read_pod<float32>();
    requires_user = buffer.read_pod<int32>();
    allow_follow_override_from_fire_direction_barrel = buffer.read_pod<int32>();
    strobe_during_fire_buildup = buffer.read_pod<int32>();
    follow_barrel_direction = buffer.read_pod<int32>();
    laser_end_point_light_hdr_scale = buffer.read_pod<float32>();
    minimum_threat_level = buffer.read_pod<float32>();
    render_beam_tiles_per_unit = buffer.read_pod<float32>();
    render_beam_rolling_speed_dust = buffer.read_pod<float32>();
    render_beam_emissive_from_threat = buffer.read_pod<float32>();
    strobe_start_frequency = buffer.read_pod<float32>();
    no_beam_position_tweak = buffer.read_pod<int32>();
    strobe_decrease_multiplier = buffer.read_pod<float32>();
    max_diff_between_barrel_and_laser = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        blackboard_enable_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    externally_controlled_aim_position = buffer.read_pod<int32>();
    laser_end_point_light_radius = buffer.read_pod<float32>();
    weapon_data_index = buffer.read_pod<int32>();
    render_beam_rolling_speed_forward = buffer.read_pod<float32>();
}

