void ADFTypes::TerrainPatch::read(IO::File& buffer) {
    TerrainMesh.read(buffer);
    TerrainPrimitive.read(buffer);
    TerrainDisplacementTexture.read(buffer);
    TerrainNormalTexture.read(buffer);
    TerrainNormalTexture16bit.read(buffer);
    TerrainNormalTextureCompressed.read(buffer);
    TerrainTriangleMapTexture.read(buffer);
    TerrainMaterialDuplexTexture.read(buffer);
    TerrainColorTexture.read(buffer);
    TerrainQualityTexture.read(buffer);
    TerrainIndirectionTexture.read(buffer);
    TerrainSSDFAtlas.read(buffer);
    MaterialPalettes.read(buffer);
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        DisplacementDownsampled = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        PalettizedMaterials = (bitfield_value >> 1) & ((1ULL << 1) - 1);
    }
    buffer.skip(4);
}

void ADFTypes::TerrainPatch::print(std::ostream &out) const {
    TerrainMesh.print(out);
    out << "TerrainPrimitive: \n";
    TerrainPrimitive.print(out);
    out << "\n";
    TerrainDisplacementTexture.print(out);
    TerrainNormalTexture.print(out);
    TerrainNormalTexture16bit.print(out);
    TerrainNormalTextureCompressed.print(out);
    TerrainTriangleMapTexture.print(out);
    TerrainMaterialDuplexTexture.print(out);
    TerrainColorTexture.print(out);
    TerrainQualityTexture.print(out);
    TerrainIndirectionTexture.print(out);
    TerrainSSDFAtlas.print(out);
    MaterialPalettes.print(out);
    out << "DisplacementDownsampled: " << DisplacementDownsampled << "\n";
    out << "PalettizedMaterials: " << PalettizedMaterials << "\n";
}

nlohmann::json ADFTypes::TerrainPatch::to_json() const {
    nlohmann::json _res;
    _res["TerrainMesh"] = TerrainMesh.to_json();
    _res["TerrainPrimitive"] = TerrainPrimitive.to_json();
    _res["TerrainDisplacementTexture"] = TerrainDisplacementTexture.to_json();
    _res["TerrainNormalTexture"] = TerrainNormalTexture.to_json();
    _res["TerrainNormalTexture16bit"] = TerrainNormalTexture16bit.to_json();
    _res["TerrainNormalTextureCompressed"] = TerrainNormalTextureCompressed.to_json();
    _res["TerrainTriangleMapTexture"] = TerrainTriangleMapTexture.to_json();
    _res["TerrainMaterialDuplexTexture"] = TerrainMaterialDuplexTexture.to_json();
    _res["TerrainColorTexture"] = TerrainColorTexture.to_json();
    _res["TerrainQualityTexture"] = TerrainQualityTexture.to_json();
    _res["TerrainIndirectionTexture"] = TerrainIndirectionTexture.to_json();
    _res["TerrainSSDFAtlas"] = TerrainSSDFAtlas.to_json();
    _res["MaterialPalettes"] = MaterialPalettes.to_json();
    _res["DisplacementDownsampled"] = DisplacementDownsampled;
    _res["PalettizedMaterials"] = PalettizedMaterials;
    return _res;
}

