void ADFTypes::CompressedData::read(IO::File& buffer) {
    UncompressedSize = buffer.read_pod<uint32>();
    buffer.skip(4);
    Data.read(buffer);
    UncompressAllocator = static_cast<ADFTypes::MemAllocator>(buffer.read_pod<uint32>());
    buffer.skip(4);
}

