    out << "DetailMaxDistance: " << DetailMaxDistance << "\n";
    out << "DetailLinearity: " << DetailLinearity << "\n";
    out << "DetailEnergyRadius: " << DetailEnergyRadius << "\n";
    out << "FadeOutTime: " << FadeOutTime << "\n";
    out << "FadeInTime: " << FadeInTime << "\n";
    out << "ZoneHeight: " << ZoneHeight << "\n";
    out << "DebugColor: \n";
    DebugColor.print(out);
