void ADFTypes::CRoadData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    terrain_material_primitive_pad = buffer.read_pod<float32>();
    sidewalk_offset_right = buffer.read_pod<float32>();
    sidewalk_right = buffer.read_pod<float32>();
    buffer.skip(4);
    _normal_intensity.read(buffer);
    decoration_random_seed = buffer.read_pod<int32>();
    sweep_profile = buffer.read_pod<int32>();
    width_padding = buffer.read_pod<float32>();
    _visual_type = buffer.read_pod<int32>();
    _width_scale.read(buffer);
    terrain_influence_radius = buffer.read_pod<float32>();
    buffer.skip(4);
    _terrain_control_point_left_falloff.read(buffer);
    _terrain_control_point_log_weight.read(buffer);
    terrain_height_scale = buffer.read_pod<float32>();
    buffer.skip(4);
    spline.read(buffer);
    override_painted_materials = buffer.read_pod<int32>();
    sort_bias = buffer.read_pod<int32>();
    draw_sidewalk_line = buffer.read_pod<int32>();
    attach_to_beginning = buffer.read_pod<int32>();
    _terrain_control_point_height_scale.read(buffer);
    _terrain_control_point_depth_scale.read(buffer);
    _opacity.read(buffer);
    _terrain_control_point_material_primitive_pad.read(buffer);
    _control_point_sweep_profile.read(buffer);
    _prototype1.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        _road_editing = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _fade_out_max = buffer.read_pod<float32>();
    buffer.skip(4);
    _terrain_control_point_right_falloff.read(buffer);
    _fade_out_min = buffer.read_pod<float32>();
    size = buffer.read_pod<int32>();
    attach_to_end = buffer.read_pod<int32>();
    buffer.skip(4);
    _terrain_control_point_influence_radius.read(buffer);
    _terrain_control_point_left_padding.read(buffer);
    sidewalk_left = buffer.read_pod<float32>();
    traverse_type = buffer.read_pod<int32>();
    material_id = buffer.read_pod<int32>();
    buffer.skip(4);
    _terrain_control_point_left_slope.read(buffer);
    terrain_log_weight = buffer.read_pod<float32>();
    buffer.skip(4);
    _terrain_control_point_right_padding.read(buffer);
    terrain_falloff = buffer.read_pod<float32>();
    roadgraph_enable = buffer.read_pod<int32>();
    _terrain_control_point_right_slope.read(buffer);
    generate_material_primitive = buffer.read_pod<int32>();
    road_type = buffer.read_pod<int32>();
    traffic_scalar = buffer.read_pod<float32>();
    terrain_falloff_noise = buffer.read_pod<float32>();
    is_visible = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    terrain_slope = buffer.read_pod<float32>();
    terrain_tunnel_noise = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    terrain_depth_scale = buffer.read_pod<float32>();
    buffer.skip(4);
    _layer3.read(buffer);
    _layer2.read(buffer);
    _layer4.read(buffer);
    speed_limit = buffer.read_pod<int32>();
    tunnel_material_id = buffer.read_pod<int32>();
    _texture_index.read(buffer);
    flags = buffer.read_pod<int32>();
    sidewalk_offset_left = buffer.read_pod<float32>();
    _prototype0.read(buffer);
    _banking.read(buffer);
    valid = buffer.read_pod<int32>();
    decoration_set = buffer.read_pod<int32>();
}

