    out << "turn_steering_factor: " << turn_steering_factor << "\n";
    out << "pitch_steering_factor: " << pitch_steering_factor << "\n";
    out << "roll_steering_factor: " << roll_steering_factor << "\n";
    out << "air_density: " << air_density << "\n";
    out << "frontal_area: " << frontal_area << "\n";
    out << "drag_coefficient: " << drag_coefficient << "\n";
