void ADFTypes::CVegetationSoundContainerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_enable.read(buffer);
    for(int i = 0; i < 2; ++i) {
        spawn_range[i] = buffer.read_pod<float32>();
    }
    scanning_pattern = buffer.read_pod<int32>();
    scan_radius = buffer.read_pod<int32>();
    enabled = buffer.read_pod<int32>();
    emitter_angle_spawn_pattern = buffer.read_pod<int32>();
    send_vegetation_height_data = buffer.read_pod<int32>();
    for(int i = 0; i < 2; ++i) {
        despawn_offset_factor[i] = buffer.read_pod<float32>();
    }
    _exportable = buffer.read_pod<int32>();
    bound_veg_layer = buffer.read_pod<int32>();
    max_scanned_instances = buffer.read_pod<int32>();
    event_disable.read(buffer);
    send_vegetation_distance_data = buffer.read_pod<int32>();
    scan_spread_factor = buffer.read_pod<int32>();
}

