void ADFTypes::CMovementTriggerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    on_movement_stopped.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    stationary_time_required = buffer.read_pod<float32>();
    buffer.skip(4);
    on_movement_started.read(buffer);
    start_stationary = buffer.read_pod<int32>();
    rotation_drift_threshold = buffer.read_pod<float32>();
    linear_speed_threshold = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    translation_drift_threshold = buffer.read_pod<float32>();
    on_translation_drift.read(buffer);
    angular_speed_threshold = buffer.read_pod<float32>();
    buffer.skip(4);
    on_rotation_drift.read(buffer);
}

void ADFTypes::CMovementTriggerData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    on_movement_stopped.print(out);
    out << "name: " << name << "\n";
    out << "stationary_time_required: " << stationary_time_required << "\n";
    on_movement_started.print(out);
    out << "start_stationary: " << start_stationary << "\n";
    out << "rotation_drift_threshold: " << rotation_drift_threshold << "\n";
    out << "linear_speed_threshold: " << linear_speed_threshold << "\n";
    out << "world: \n";
    world.print(out);
    out << "\n";
    out << "translation_drift_threshold: " << translation_drift_threshold << "\n";
    on_translation_drift.print(out);
    out << "angular_speed_threshold: " << angular_speed_threshold << "\n";
    on_rotation_drift.print(out);
}

nlohmann::json ADFTypes::CMovementTriggerData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["on_movement_stopped"] = on_movement_stopped.to_json();
    _res["name"] = name;
    _res["stationary_time_required"] = stationary_time_required;
    _res["on_movement_started"] = on_movement_started.to_json();
    _res["start_stationary"] = start_stationary;
    _res["rotation_drift_threshold"] = rotation_drift_threshold;
    _res["linear_speed_threshold"] = linear_speed_threshold;
    _res["world"] = world.to_json();
    _res["translation_drift_threshold"] = translation_drift_threshold;
    _res["on_translation_drift"] = on_translation_drift.to_json();
    _res["angular_speed_threshold"] = angular_speed_threshold;
    _res["on_rotation_drift"] = on_rotation_drift.to_json();
    return _res;
}

