void ADFTypes::HairConstants::read(IO::File& buffer) {
    SpecularGloss = buffer.read_pod<float32>();
    TransmissionIntensity = buffer.read_pod<float32>();
    SpecularFresnel = buffer.read_pod<float32>();
    DiffuseWrap = buffer.read_pod<float32>();
    DiffuseRoughness = buffer.read_pod<float32>();
    AnisotropicStrength = buffer.read_pod<float32>();
    AnisotropicX = buffer.read_pod<float32>();
    AnisotropicY = buffer.read_pod<float32>();
    RimStrength = buffer.read_pod<float32>();
    RingStrength = buffer.read_pod<float32>();
    RingAngle = buffer.read_pod<float32>();
    RingOffset = buffer.read_pod<float32>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        DoubleSided = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        AlphaTest = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        AlphaBlending = (bitfield_value >> 2) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

void ADFTypes::HairConstants::print(std::ostream &out) const {
    out << "SpecularGloss: " << SpecularGloss << "\n";
    out << "TransmissionIntensity: " << TransmissionIntensity << "\n";
    out << "SpecularFresnel: " << SpecularFresnel << "\n";
    out << "DiffuseWrap: " << DiffuseWrap << "\n";
    out << "DiffuseRoughness: " << DiffuseRoughness << "\n";
    out << "AnisotropicStrength: " << AnisotropicStrength << "\n";
    out << "AnisotropicX: " << AnisotropicX << "\n";
    out << "AnisotropicY: " << AnisotropicY << "\n";
    out << "RimStrength: " << RimStrength << "\n";
    out << "RingStrength: " << RingStrength << "\n";
    out << "RingAngle: " << RingAngle << "\n";
    out << "RingOffset: " << RingOffset << "\n";
    out << "DoubleSided: " << DoubleSided << "\n";
    out << "AlphaTest: " << AlphaTest << "\n";
    out << "AlphaBlending: " << AlphaBlending << "\n";
}

nlohmann::json ADFTypes::HairConstants::to_json() const {
    nlohmann::json _res;
    _res["SpecularGloss"] = SpecularGloss;
    _res["TransmissionIntensity"] = TransmissionIntensity;
    _res["SpecularFresnel"] = SpecularFresnel;
    _res["DiffuseWrap"] = DiffuseWrap;
    _res["DiffuseRoughness"] = DiffuseRoughness;
    _res["AnisotropicStrength"] = AnisotropicStrength;
    _res["AnisotropicX"] = AnisotropicX;
    _res["AnisotropicY"] = AnisotropicY;
    _res["RimStrength"] = RimStrength;
    _res["RingStrength"] = RingStrength;
    _res["RingAngle"] = RingAngle;
    _res["RingOffset"] = RingOffset;
    _res["DoubleSided"] = DoubleSided;
    _res["AlphaTest"] = AlphaTest;
    _res["AlphaBlending"] = AlphaBlending;
    return _res;
}

