void ADFTypes::AmfBuffer::read(IO::File& buffer) {
    Data.read(buffer);
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        CreateSRV = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(7);
}

