void ADFTypes::CPointAtObjectData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    offset_min_max_pitch = buffer.read_pod<float32>();
    buffer.skip(4);
    not_los_event.read(buffer);
    min_pitch = buffer.read_pod<float32>();
    goto_default_when_no_target = buffer.read_pod<int32>();
    target_tag = buffer.read_pod<int32>();
    buffer.skip(4);
    targeting_success_event.read(buffer);
    ended_targeting_event.read(buffer);
    targeting_fail_event.read(buffer);
    yaw_constraint.read(buffer);
    can_target_outside_pitch_limit = buffer.read_pod<int32>();
    can_target_outside_yaw_limit = buffer.read_pod<int32>();
    picked_target.read(buffer);
    max_rotation_speed = buffer.read_pod<float32>();
    min_yaw = buffer.read_pod<float32>();
    targeting_success_max_yaw = buffer.read_pod<float32>();
    buffer.skip(4);
    check_line_of_sight_event.read(buffer);
    disable_event.read(buffer);
    started_targeting_event.read(buffer);
    min_dist = buffer.read_pod<float32>();
    buffer.skip(4);
    pitch_constraint.read(buffer);
    max_pitch = buffer.read_pod<float32>();
    target_player_only = buffer.read_pod<int32>();
    deactivate_event.read(buffer);
    active = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    has_los_event.read(buffer);
    max_yaw = buffer.read_pod<float32>();
    targeting_success_max_pitch = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    max_rotation_acceleration = buffer.read_pod<float32>();
    enabled = buffer.read_pod<int32>();
    range = buffer.read_pod<float32>();
    goto_default_when_deactivated = buffer.read_pod<int32>();
    activate_event.read(buffer);
    enable_event.read(buffer);
}

