void ADFTypes::CSupportItemGrenadeData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    spawn_bonus_grenades = buffer.read_pod<int32>();
    remote_detonate_interval = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    clone_factory_ref.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        diffuse_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    automatic_remote_detonation_trigger_distance = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        normal_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    clone_factory_ref_level2.read(buffer);
    max_remote_detonate_grenades = buffer.read_pod<int32>();
    throw_in_arc = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        properties_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    can_remote_detonate = buffer.read_pod<int32>();
    show_arc = buffer.read_pod<int32>();
    throw_speed = buffer.read_pod<float32>();
    buffer.skip(4);
    clone_factory_ref_level3.read(buffer);
    bonus_grenade_angle = buffer.read_pod<float32>();
    buffer.skip(4);
    clone_factory_ref_level1.read(buffer);
    initial_grenade_gravity = buffer.read_pod<float32>();
    buffer.skip(4);
}

