void ADFTypes::Propellers::read(IO::File& buffer) {
    max_thrust = buffer.read_pod<float32>();
    max_rpm = buffer.read_pod<float32>();
    max_reverse_rpm = buffer.read_pod<float32>();
    diameter = buffer.read_pod<float32>();
    pitch = buffer.read_pod<float32>();
    docking_controls.read(buffer);
    thrust_vs_advance_ratio.read(buffer);
    max_steering_vs_speed_ms.read(buffer);
    trim_deg_vs_speed_ms.read(buffer);
    buffer.skip(4);
    for(int i = 0; i < 2; ++i) {
        propellers[i].read(buffer);
    }
    number_of_propellers = buffer.read_pod<uint8>();
    buffer.skip(7);
}

void ADFTypes::Propellers::print(std::ostream &out) const {
    out << "max_thrust: " << max_thrust << "\n";
    out << "max_rpm: " << max_rpm << "\n";
    out << "max_reverse_rpm: " << max_reverse_rpm << "\n";
    out << "diameter: " << diameter << "\n";
    out << "pitch: " << pitch << "\n";
    docking_controls.print(out);
    thrust_vs_advance_ratio.print(out);
    max_steering_vs_speed_ms.print(out);
    trim_deg_vs_speed_ms.print(out);
    out << "propellers: \n";
    propellers.print(out);
    out << "\n";
    out << "number_of_propellers: " << number_of_propellers << "\n";
}

nlohmann::json ADFTypes::Propellers::to_json() const {
    nlohmann::json _res;
    _res["max_thrust"] = max_thrust;
    _res["max_rpm"] = max_rpm;
    _res["max_reverse_rpm"] = max_reverse_rpm;
    _res["diameter"] = diameter;
    _res["pitch"] = pitch;
    _res["docking_controls"] = docking_controls.to_json();
    _res["thrust_vs_advance_ratio"] = thrust_vs_advance_ratio.to_json();
    _res["max_steering_vs_speed_ms"] = max_steering_vs_speed_ms.to_json();
    _res["trim_deg_vs_speed_ms"] = trim_deg_vs_speed_ms.to_json();
    _res["propellers"] = propellers.to_json();
    _res["number_of_propellers"] = number_of_propellers;
    return _res;
}

