void ADFTypes::CWorldLocationData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    force_unhibernate_event.read(buffer);
    undiscover_distance = buffer.read_pod<float32>();
    buffer.skip(4);
    exited_event.read(buffer);
    exit_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        sound_module_variable_prefix = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        location_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    is_hub = buffer.read_pod<int32>();
    gui_name = buffer.read_pod<int32>();
    goal_completed_ui_notification_finished_event.read(buffer);
    force_disable_event.read(buffer);
    force_discover_event.read(buffer);
    discovered_event.read(buffer);
    force_fully_complete_event.read(buffer);
    force_hidden_event.read(buffer);
    enter_event.read(buffer);
    initial_state = buffer.read_pod<int32>();
    buffer.skip(4);
    revealed_event.read(buffer);
    undiscovered_event.read(buffer);
    reward_package_ref.read(buffer);
    faction = buffer.read_pod<int32>();
    buffer.skip(4);
    entered_event.read(buffer);
    goal_completed_event.read(buffer);
    gui_description = buffer.read_pod<int32>();
    difficulty = buffer.read_pod<int32>();
    sound_module_controller_tag_receiving_data = buffer.read_pod<int32>();
    buffer.skip(4);
    force_goal_complete_event.read(buffer);
    reveal_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    disabled_event.read(buffer);
    fully_completed_event.read(buffer);
    force_undiscover_event.read(buffer);
    sound_module_receiving_data = buffer.read_pod<int32>();
    buffer.skip(4);
    hidden_event.read(buffer);
    force_hibernate_event.read(buffer);
}

