void ADFTypes::AimConstraint::read(IO::File& buffer) {
    source_joint.read(buffer);
    target_joint.read(buffer);
    source_joint_index = buffer.read_pod<int8>();
    target_joint_index = buffer.read_pod<int8>();
    buffer.skip(2);
    world_up_type = static_cast<ADFTypes::AimConstraintWorldUpType>(buffer.read_pod<uint32>());
    world_up_joint_index = buffer.read_pod<int8>();
    buffer.skip(3);
    for(int i = 0; i < 3; ++i) {
        aim_vector[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        up_vector[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        world_up_vector[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        angle_offset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        constrained_rotation_axes[i] = buffer.read_pod<int8>();
    }
    buffer.skip(1);
}

