void ADFTypes::CGiveRewardPackageData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    notify_reward_package_ui = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::CGiveRewardPackageData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "notify_reward_package_ui: " << notify_reward_package_ui << "\n";
    out << "name: " << name << "\n";
}

nlohmann::json ADFTypes::CGiveRewardPackageData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["notify_reward_package_ui"] = notify_reward_package_ui;
    _res["name"] = name;
    return _res;
}

