void ADFTypes::AnimationTrack::read(IO::File& buffer) {
    AnimationId.read(buffer);
    buffer.skip(4);
    SubFiles.read(buffer);
    AdditiveFiles.read(buffer);
    MirrorFiles.read(buffer);
    Segments.read(buffer);
    RetargetSourceSkeletons.read(buffer);
    RetargetTargetSkeletons.read(buffer);
    SegmentAssociations.read(buffer);
    BlendCurves.read(buffer);
    TrackEvents.read(buffer);
    OrderedModifiers.read(buffer);
    TrackMessages.read(buffer);
    LateStartTime = buffer.read_pod<float32>();
    PlaybackSpeed = buffer.read_pod<float32>();
    PhaseMatchMode = buffer.read_pod<int32>();
    TransitionFromTime = buffer.read_pod<float32>();
    StateReenterMode = buffer.read_pod<int32>();
    PlayMode = buffer.read_pod<int32>();
    BlendInCurve = buffer.read_pod<int32>();
    WeightNormalization = buffer.read_pod<int32>();
    EarlyFinishTime = buffer.read_pod<float32>();
    TransitionToTime = buffer.read_pod<float32>();
    BlendOutCurve = buffer.read_pod<int32>();
    TransitionMode = buffer.read_pod<int32>();
    BlendMode = buffer.read_pod<int32>();
    StartVariationIndex = buffer.read_pod<int32>();
    CustomPlayTimeSupport = buffer.read_pod<uint8>();
    buffer.skip(7);
}

