    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    gas_time_at_full_size = buffer.read_pod<float32>();
    faction = buffer.read_pod<int32>();
    on_gas_full.read(buffer);
    gas_start_delay = buffer.read_pod<float32>();
    gas_time_to_full_size = buffer.read_pod<float32>();
    disable.read(buffer);
    damage_type = buffer.read_pod<int32>();
    buffer.skip(4);
    on_gas_fade_start.read(buffer);
    on_gas_begin.read(buffer);
    gas_damage_per_sec = buffer.read_pod<int32>();
    buffer.skip(4);
    on_gas_fade_end.read(buffer);
