void ADFTypes::CSearchLightData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    LightsOff_OnEvent.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    SearchSpeed = buffer.read_pod<float32>();
    buffer.skip(4);
    StartOnEvent.read(buffer);
    SearchSpline.read(buffer);
    PlayerLostEvent.read(buffer);
    ResetOnEvent.read(buffer);
    ConeAngle = buffer.read_pod<float32>();
    buffer.skip(4);
    LightsOn_OnEvent.read(buffer);
    LightIntensity = buffer.read_pod<float32>();
    buffer.skip(4);
    StopOnEvent.read(buffer);
    StopForcedTargetTracking.read(buffer);
    LingerTime = buffer.read_pod<float32>();
    PlayerFoundTime = buffer.read_pod<float32>();
    StartForcedTargetTracking.read(buffer);
    TraceSpeed = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    LoopMode = buffer.read_pod<int32>();
    MaxDistanceToTarget = buffer.read_pod<float32>();
    buffer.skip(4);
    PlayerFoundEvent.read(buffer);
}

void ADFTypes::CSearchLightData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    LightsOff_OnEvent.print(out);
    out << "name: " << name << "\n";
    out << "SearchSpeed: " << SearchSpeed << "\n";
    StartOnEvent.print(out);
    SearchSpline.print(out);
    PlayerLostEvent.print(out);
    ResetOnEvent.print(out);
    out << "ConeAngle: " << ConeAngle << "\n";
    LightsOn_OnEvent.print(out);
    out << "LightIntensity: " << LightIntensity << "\n";
    StopOnEvent.print(out);
    StopForcedTargetTracking.print(out);
    out << "LingerTime: " << LingerTime << "\n";
    out << "PlayerFoundTime: " << PlayerFoundTime << "\n";
    StartForcedTargetTracking.print(out);
    out << "TraceSpeed: " << TraceSpeed << "\n";
    out << "world: \n";
    world.print(out);
    out << "\n";
    out << "LoopMode: " << LoopMode << "\n";
    out << "MaxDistanceToTarget: " << MaxDistanceToTarget << "\n";
    PlayerFoundEvent.print(out);
}

