void ADFTypes::WorldLocation::read(IO::File& buffer) {
    LocationId = buffer.read_pod<uint32>();
    LocationNameHash = buffer.read_pod<uint32>();
    RegionNameHash = buffer.read_pod<uint32>();
    InitialState = buffer.read_pod<uint8>();
    buffer.skip(3);
    Faction = buffer.read_pod<int32>();
    Difficulty = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        Position[i] = buffer.read_pod<float32>();
    }
    UndiscoverDistance = buffer.read_pod<float32>();
    GuiName = buffer.read_pod<uint32>();
    GuiDescription = buffer.read_pod<uint32>();
    IsHub = buffer.read_pod<uint8>();
    buffer.skip(3);
    SoundModuleReceivingData = buffer.read_pod<uint32>();
    SoundModuleControllerTagReceivingData = buffer.read_pod<uint32>();
    for(int i = 0; i < 6; ++i) {
        SoundModuleVariables[i] = buffer.read_pod<uint32>();
    }
    buffer.skip(4);
    ForceHibernateEvent.read(buffer);
    ForceUnHibernateEvent.read(buffer);
    ForceDisableEvent.read(buffer);
    ForceHiddenEvent.read(buffer);
    ForceUndiscoverEvent.read(buffer);
    RevealEvent.read(buffer);
    ForceDiscoverEvent.read(buffer);
    ForceGoalCompleteEvent.read(buffer);
    ForceFullyCompleteEvent.read(buffer);
    EnterEvent.read(buffer);
    ExitEvent.read(buffer);
    DisabledEvent.read(buffer);
    HiddenEvent.read(buffer);
    UndiscoveredEvent.read(buffer);
    RevealedEvent.read(buffer);
    DiscoveredEvent.read(buffer);
    GoalCompletedEvent.read(buffer);
    FullyCompletedEvent.read(buffer);
    EnteredEvent.read(buffer);
    ExitedEvent.read(buffer);
    GoalCompletedUiNotificationFinishedEvent.read(buffer);
    TrackedLocationItems.read(buffer);
    RewardPackages.read(buffer);
    ShopNameHashes.read(buffer);
}

