void ADFTypes::CSoundModuleSendFunctionData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    send_function_on_disabled = buffer.read_pod<int32>();
    retrigger_send_urgency = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_enable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        function = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    send_function_on_removed_from_world = buffer.read_pod<int32>();
    enabled = buffer.read_pod<int32>();
    retrigger_delta = buffer.read_pod<float32>();
    buffer.skip(4);
    event_stop_retriggering.read(buffer);
    event_function_sent.read(buffer);
    _exportable = buffer.read_pod<int32>();
    send_function_on_enabled = buffer.read_pod<int32>();
    retrigger_count = buffer.read_pod<int32>();
    buffer.skip(4);
    event_send_function.read(buffer);
    event_disable.read(buffer);
}

