    out << "function: " << function << "\n";
    out << "send_function_on_removed_from_world: " << send_function_on_removed_from_world << "\n";
    out << "enabled: " << enabled << "\n";
    out << "retrigger_delta: " << retrigger_delta << "\n";
    event_stop_retriggering.print(out);
    event_function_sent.print(out);
    out << "_exportable: " << _exportable << "\n";
    out << "send_function_on_enabled: " << send_function_on_enabled << "\n";
    out << "retrigger_count: " << retrigger_count << "\n";
    event_send_function.print(out);
    event_disable.print(out);
