void ADFTypes::CBulletSpawnerData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    fire_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    tuning_file = buffer.read_pod<int32>();
    horizontal_spread_angle = buffer.read_pod<float32>();
    bullet_minimum_distance_before_decal = buffer.read_pod<float32>();
    bullets_per_second_end = buffer.read_pod<int32>();
    vertical_spread_angle = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        impact_usage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    vertical_spawn_offset = buffer.read_pod<float32>();
    duration = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    bullets_per_second_start = buffer.read_pod<int32>();
    bullets_per_second_variation = buffer.read_pod<int32>();
}

