void ADFTypes::CPlacementRuleData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    despawn_self_on_spawn = buffer.read_pod<int32>();
    ground_snap = buffer.read_pod<int32>();
    orientation = buffer.read_pod<int32>();
    buffer.skip(4);
    on_spawn_event.read(buffer);
    on_hit_event.read(buffer);
    spawn_tags.read(buffer);
    block_check_auto_despawn = buffer.read_pod<int32>();
    ground_snap_align_to_radius = buffer.read_pod<float32>();
    is_cargo = buffer.read_pod<int32>();
    proximity_check = buffer.read_pod<int32>();
    on_prespawn_event.read(buffer);
    unload_auto_despawn = buffer.read_pod<int32>();
    priority = buffer.read_pod<int32>();
    on_destroy_event.read(buffer);
    attach_object.read(buffer);
    during_mission = buffer.read_pod<int32>();
    ground_snap_align_to_normal = buffer.read_pod<int32>();
    initial_interest = buffer.read_pod<int32>();
    wake_physics = buffer.read_pod<int32>();
    respawn_event.read(buffer);
    block_check = buffer.read_pod<int32>();
    los_check = buffer.read_pod<int32>();
    spawn_alias.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        mission_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    chance = buffer.read_pod<float32>();
    buffer.skip(4);
    deactivate_event.read(buffer);
    graph_object_ref.read(buffer);
    despawn_event.read(buffer);
    spawn_alias_override = buffer.read_pod<int32>();
    buffer.skip(4);
    on_world_at_war_destroy_event.read(buffer);
    graph_object_update.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    make_dynamic_on_spawn = buffer.read_pod<int32>();
    buffer.skip(4);
    graph_object_done.read(buffer);
    on_despawn_event.read(buffer);
    on_given_event.read(buffer);
    active_on_creation = buffer.read_pod<int32>();
    deactivate_on_spawn = buffer.read_pod<int32>();
    activate_event.read(buffer);
}

