void ADFTypes::COutlineData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    opacity = buffer.read_pod<float32>();
    wireframe_jitter_speed_high = buffer.read_pod<float32>();
    wireframe_interpolation_time = buffer.read_pod<float32>();
    update_wireframe = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    wireframe_jitter_speed_low = buffer.read_pod<float32>();
    visible = buffer.read_pod<int32>();
    for(int i = 0; i < 4; ++i) {
        color[i] = buffer.read_pod<float32>();
    }
    character_lod_start = buffer.read_pod<int32>();
    buffer.skip(4);
    start_increasing_wireframe_lod.read(buffer);
    wireframe_jitter_factor_low = buffer.read_pod<float32>();
    width = buffer.read_pod<int32>();
    cancel_increasing_wireframe_lod.read(buffer);
    jump_to_max_wireframe_lod.read(buffer);
    character_lod_end = buffer.read_pod<int32>();
    buffer.skip(4);
    hide_event.read(buffer);
    wireframe_jitter_factor_high = buffer.read_pod<float32>();
    type = buffer.read_pod<int32>();
    show_event.read(buffer);
}

