void ADFTypes::CMissileData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    should_split = buffer.read_pod<int32>();
    split_missile_spread_delay = buffer.read_pod<float32>();
    clone_factory.read(buffer);
    light_targeting_delay = buffer.read_pod<float32>();
    turning_speed_random = buffer.read_pod<float32>();
    curve_far_distance = buffer.read_pod<float32>();
    should_travel_straight = buffer.read_pod<int32>();
    acceleration_random_time_1 = buffer.read_pod<float32>();
    acceleration_random_time_0 = buffer.read_pod<float32>();
    gravity_force = buffer.read_pod<float32>();
    initial_speed = buffer.read_pod<float32>();
    curve_pitch_max = buffer.read_pod<float32>();
    acceleration_0 = buffer.read_pod<float32>();
    use_homing_ray_on_player_target = buffer.read_pod<int32>();
    no_turning_time = buffer.read_pod<float32>();
    curve_yaw_max = buffer.read_pod<float32>();
    curve_near_distance = buffer.read_pod<float32>();
    reset_system_group_time = buffer.read_pod<float32>();
    buffer.skip(4);
    trail_sound.read(buffer);
    acceleration_time_0 = buffer.read_pod<float32>();
    detonate_on_impact = buffer.read_pod<int32>();
    should_travel_straight_up_time_random = buffer.read_pod<float32>();
    should_travel_straight_up_time = buffer.read_pod<float32>();
    use_curved_launch = buffer.read_pod<int32>();
    curve_yaw_min = buffer.read_pod<float32>();
    turn_speed_multiplier_1 = buffer.read_pod<float32>();
    light_targeting = buffer.read_pod<int32>();
    curve_pitch_min = buffer.read_pod<float32>();
    turn_speed_multiplier_0 = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        trail_position[i] = buffer.read_pod<float32>();
    }
    gravity_factor = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        collision_model_file = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    trail_effect = buffer.read_pod<int32>();
    target_indication_effect = buffer.read_pod<int32>();
    detonation_time_random = buffer.read_pod<float32>();
    number_of_split_missiles = buffer.read_pod<int32>();
    max_insane_radius = buffer.read_pod<float32>();
    exclude_holder_damage = buffer.read_pod<int32>();
    detonation_time = buffer.read_pod<float32>();
    multi_target_damage_multiplier = buffer.read_pod<float32>();
    missile_force_detonate_event.read(buffer);
    loose_lock_distance = buffer.read_pod<float32>();
    acceleration_random_0 = buffer.read_pod<float32>();
    acceleration_random_1 = buffer.read_pod<float32>();
    split_delay = buffer.read_pod<float32>();
    on_missile_evade.read(buffer);
    force_pulse_ref.read(buffer);
    no_blend_out_of_relative_velocity = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    should_travel_straight_up = buffer.read_pod<int32>();
    turning_speed = buffer.read_pod<float32>();
    acceleration_time_1 = buffer.read_pod<float32>();
    override_rotation_with_holder_rotation = buffer.read_pod<int32>();
    acceleration_1 = buffer.read_pod<float32>();
    buffer.skip(4);
    impact_clone_factory.read(buffer);
    max_insane_speed = buffer.read_pod<float32>();
    buffer.skip(4);
}

