void ADFTypes::CTurretObjectData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    raise_vehicle_part_name = buffer.read_pod<int32>();
    debug_track_player = buffer.read_pod<int32>();
    interaction_context.read(buffer);
    aim_tracking_reset_timeout = buffer.read_pod<float32>();
    ignore_holder = buffer.read_pod<int32>();
    cannon_vehicle_part_name = buffer.read_pod<int32>();
    turret_vehicle_part_name = buffer.read_pod<int32>();
    difficulty_level = buffer.read_pod<float32>();
    faction = buffer.read_pod<int32>();
    auto_fire_sensor_fov = buffer.read_pod<float32>();
    buffer.skip(4);
    on_deactivate_event.read(buffer);
    auto_fire_sensor_depth = buffer.read_pod<float32>();
    rotation_speed = buffer.read_pod<float32>();
    door_id = buffer.read_pod<int32>();
    buffer.skip(4);
    on_activate_event.read(buffer);
    cannon_turning_speed = buffer.read_pod<float32>();
    aim_tracking_reset_on_deactivate = buffer.read_pod<int32>();
    faction_presence = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    raise_target_height = buffer.read_pod<float32>();
    debug_warn_auto_fire_warm_up = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    turret_turning_speed = buffer.read_pod<float32>();
    aim_tracking_reset_pre_delay_time = buffer.read_pod<float32>();
    damageable_ref.read(buffer);
    auto_fire_sensor_warm_up_time = buffer.read_pod<float32>();
    buffer.skip(4);
    ai_weapon_hint_transform_ref.read(buffer);
    use_ai_entity = buffer.read_pod<int32>();
    buffer.skip(4);
    owner_ref.read(buffer);
    aim_tracking_reset_post_settle_time = buffer.read_pod<float32>();
    buffer.skip(4);
}

