    buffer.skip(4);
    nametag1.read(buffer);
    nametag2.read(buffer);
    for(int i = 0; i < 16; ++i) {
        object1_initial_transform[i] = buffer.read_pod<float32>();
    }
    reuse_collision_group.read(buffer);
    on_constraint_disabled.read(buffer);
    for(int i = 0; i < 16; ++i) {
        object2_initial_transform[i] = buffer.read_pod<float32>();
    }
    solver_inertia_multiplier_object2 = buffer.read_pod<float32>();
