    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        reuse_collision_group_nametag = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enable.read(buffer);
    reuse_collision_group_terrain = buffer.read_pod<int32>();
    buffer.skip(4);
    disable.read(buffer);
    disable_motor.read(buffer);
    active = buffer.read_pod<int32>();
    object2_use_initial_transform = buffer.read_pod<int32>();
    disable_reuse_collision_group_terrain.read(buffer);
    set_not_active.read(buffer);
    keep_system_group_object2 = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    keep_system_group_object1 = buffer.read_pod<int32>();
    buffer.skip(4);
    on_constraint_enabled.read(buffer);
    set_active.read(buffer);
    enabled = buffer.read_pod<int32>();
    buffer.skip(4);
    enable_object_collision.read(buffer);
    motors_enabled_on_start = buffer.read_pod<int32>();
    buffer.skip(4);
