void ADFTypes::SBountyEnemyTypeData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    enable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    weapon_tag.read(buffer);
    spawn_tag.read(buffer);
    enabled = buffer.read_pod<int32>();
    buffer.skip(4);
    disable.read(buffer);
    spawn_points = buffer.read_pod<int32>();
    unique_id = buffer.read_pod<int32>();
}

void ADFTypes::SBountyEnemyTypeData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    enable.print(out);
    out << "name: " << name << "\n";
    out << "weapon_tag: \n";
    weapon_tag.print(out);
    out << "\n";
    out << "spawn_tag: \n";
    spawn_tag.print(out);
    out << "\n";
    out << "enabled: " << enabled << "\n";
    disable.print(out);
    out << "spawn_points: " << spawn_points << "\n";
    out << "unique_id: " << unique_id << "\n";
}

nlohmann::json ADFTypes::SBountyEnemyTypeData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["enable"] = enable.to_json();
    _res["name"] = name;
    _res["weapon_tag"] = weapon_tag.to_json();
    _res["spawn_tag"] = spawn_tag.to_json();
    _res["enabled"] = enabled;
    _res["disable"] = disable.to_json();
    _res["spawn_points"] = spawn_points;
    _res["unique_id"] = unique_id;
    return _res;
}

