void ADFTypes::GeneralMeshConstants::read(IO::File& buffer) {
    PristineIndexCount = buffer.read_pod<uint32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        IsDestructionMesh = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        IsSkinnedMesh = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        IsAnimMesh = (bitfield_value >> 2) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
}

void ADFTypes::GeneralMeshConstants::print(std::ostream &out) const {
    out << "PristineIndexCount: " << PristineIndexCount << "\n";
    out << "IsDestructionMesh: " << IsDestructionMesh << "\n";
    out << "IsSkinnedMesh: " << IsSkinnedMesh << "\n";
    out << "IsAnimMesh: " << IsAnimMesh << "\n";
}

nlohmann::json ADFTypes::GeneralMeshConstants::to_json() const {
    nlohmann::json _res;
    _res["PristineIndexCount"] = PristineIndexCount;
    _res["IsDestructionMesh"] = IsDestructionMesh;
    _res["IsSkinnedMesh"] = IsSkinnedMesh;
    _res["IsAnimMesh"] = IsAnimMesh;
    return _res;
}

