void ADFTypes::_entityinstanceData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    random_mode = buffer.read_pod<int32>();
    for(int i = 0; i < 4; ++i) {
        _flow_rect[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 16; ++i) {
        _pre_attach_height[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        tags = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    navmesh_merge = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        transform[i] = buffer.read_pod<float32>();
    }
    attachtomesh = buffer.read_pod<int32>();
    attachtoground = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        event_scopes = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    attach_max_tilt = buffer.read_pod<float32>();
    random_probability = buffer.read_pod<float32>();
    add_referenced_fmod_banks = buffer.read_pod<int32>();
    attachtowater = buffer.read_pod<int32>();
}

void ADFTypes::_entityinstanceData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "random_mode: " << random_mode << "\n";
    out << "_flow_rect: \n";
    _flow_rect.print(out);
    out << "\n";
    out << "_pre_attach_height: \n";
    _pre_attach_height.print(out);
    out << "\n";
    out << "tags: " << tags << "\n";
    out << "navmesh_merge: " << navmesh_merge << "\n";
    out << "transform: \n";
    transform.print(out);
    out << "\n";
    out << "attachtomesh: " << attachtomesh << "\n";
    out << "attachtoground: " << attachtoground << "\n";
    out << "event_scopes: " << event_scopes << "\n";
    out << "attach_max_tilt: " << attach_max_tilt << "\n";
    out << "random_probability: " << random_probability << "\n";
    out << "add_referenced_fmod_banks: " << add_referenced_fmod_banks << "\n";
    out << "attachtowater: " << attachtowater << "\n";
}

nlohmann::json ADFTypes::_entityinstanceData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["random_mode"] = random_mode;
    _res["_flow_rect"] = _flow_rect.to_json();
    _res["_pre_attach_height"] = _pre_attach_height.to_json();
    _res["tags"] = tags;
    _res["navmesh_merge"] = navmesh_merge;
    _res["transform"] = transform.to_json();
    _res["attachtomesh"] = attachtomesh;
    _res["attachtoground"] = attachtoground;
    _res["event_scopes"] = event_scopes;
    _res["attach_max_tilt"] = attach_max_tilt;
    _res["random_probability"] = random_probability;
    _res["add_referenced_fmod_banks"] = add_referenced_fmod_banks;
    _res["attachtowater"] = attachtowater;
    return _res;
}

