void ADFTypes::CRigidObjectData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    add_to_sound_obstruction_density = buffer.read_pod<int32>();
    flag_slopes = buffer.read_pod<int32>();
    _rigid_object_adf_data_index = buffer.read_pod<int32>();
    debris = buffer.read_pod<int32>();
    reload_physics_event.read(buffer);
    pre_draw = buffer.read_pod<int32>();
    physics_effects_tuning = buffer.read_pod<int32>();
    collision_enabled = buffer.read_pod<int32>();
    sky_occluder = buffer.read_pod<int32>();
    dynamic_priority_scale = buffer.read_pod<float32>();
    buffer.skip(4);
    emissive_light_ref.read(buffer);
    save_transform = buffer.read_pod<int32>();
    buffer.skip(4);
    enable_magnetic_reaction.read(buffer);
    for(int i = 0; i < 16; ++i) {
        world[i] = buffer.read_pod<float32>();
    }
    disable_magnetic_reaction.read(buffer);
    disable_collision_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _dynamic_pathfinding_mask = buffer.read_pod<int32>();
    send_to_reverb = buffer.read_pod<int32>();
    automate_sound_obstruction_radius_from_bounding_box = buffer.read_pod<int32>();
    for(int i = 0; i < 16; ++i) {
        render_offset[i] = buffer.read_pod<float32>();
    }
    sound_occlusion = buffer.read_pod<int32>();
    inherit_parent_transform = buffer.read_pod<int32>();
    reflect_in_water = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        scrubber_color[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    reenable_collision_event.read(buffer);
    magnetic_reaction_enabled = buffer.read_pod<int32>();
    static_pathfinding = buffer.read_pod<int32>();
    force_daytime_emissive = buffer.read_pod<int32>();
    dynamic_pathfinding = buffer.read_pod<int32>();
    filename = buffer.read_pod<int32>();
    buffer.skip(4);
    on_tether_stop.read(buffer);
    impact_damage_multiplier = buffer.read_pod<float32>();
    buffer.skip(4);
    fade_out.read(buffer);
    size_cull = buffer.read_pod<int32>();
    buffer.skip(4);
    target_enable.read(buffer);
    physics_effect_layer_alias.read(buffer);
    showonevent.read(buffer);
    passthru_damage_target.read(buffer);
    log_to_scrubber = buffer.read_pod<int32>();
    visible = buffer.read_pod<int32>();
    bullet_hit_impulse_multiplier = buffer.read_pod<float32>();
    buffer.skip(4);
    on_tether.read(buffer);
    stealth_cloak = buffer.read_pod<int32>();
    magnet_reaction_event_cooldown = buffer.read_pod<float32>();
    type = buffer.read_pod<int32>();
    transform_hierarchy_type = buffer.read_pod<int32>();
    dynamic_object_is_climbable_by_player = buffer.read_pod<int32>();
    static_mesh_detail = buffer.read_pod<int32>();
    stop_key_frame.read(buffer);
    sound_obstruction_radius = buffer.read_pod<float32>();
    clip = buffer.read_pod<int32>();
    target_disable.read(buffer);
    collision = buffer.read_pod<int32>();
    buffer.skip(4);
    make_fixed.read(buffer);
    hideonevent.read(buffer);
    force_activate_on_spawn = buffer.read_pod<int32>();
    cast_shadows = buffer.read_pod<int32>();
    far_location_inclusion = buffer.read_pod<int32>();
    fixed_object_is_climbable_by_player = buffer.read_pod<int32>();
    dynamic_pathfinding_material = buffer.read_pod<int32>();
    buffer.skip(4);
    make_dynamic.read(buffer);
    magnet_reaction = buffer.read_pod<float32>();
    magnet_reaction_event_force_threshold = buffer.read_pod<float32>();
    solid_carve = buffer.read_pod<int32>();
    buffer.skip(4);
    on_magnet_reaction_event.read(buffer);
    target_start_enabled = buffer.read_pod<int32>();
    buffer.skip(4);
    start_damaged_effects_event.read(buffer);
}

