void ADFTypes::SAnimationLayerInfoData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    sort_order = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        file = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        layer_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::SAnimationLayerInfoData::print(std::ostream &out) const {
    out << "__SubObjects: \n";
    __SubObjects.print(out);
    out << "\n";
    out << "sort_order: " << sort_order << "\n";
    out << "name: " << name << "\n";
    out << "file: " << file << "\n";
    out << "layer_name: " << layer_name << "\n";
}

nlohmann::json ADFTypes::SAnimationLayerInfoData::to_json() const {
    nlohmann::json _res;
    _res["__SubObjects"] = __SubObjects.to_json();
    _res["sort_order"] = sort_order;
    _res["name"] = name;
    _res["file"] = file;
    _res["layer_name"] = layer_name;
    return _res;
}

