    tracer_time_to_live = buffer.read_pod<float32>();
    ricochet_chance = buffer.read_pod<float32>();
    smoke_trail_tile_size = buffer.read_pod<float32>();
    tracer_per_smoke_trail = buffer.read_pod<uint8>();
    bullets_per_tracer = buffer.read_pod<uint8>();
    bullets_per_shot = buffer.read_pod<uint8>();
    bullets_per_decal_per_shot = buffer.read_pod<uint8>();
    shots_fired_on_max_windup = buffer.read_pod<int32>();
    follow_weapon_translation = buffer.read_pod<uint8>();
    buffer.skip(3);
    velocity_inheritance_scale = buffer.read_pod<float32>();
