void ADFTypes::CVehiclePartConstraintToPoweredData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    enable_input = buffer.read_pod<int32>();
    motor_damping = buffer.read_pod<float32>();
    disable_limits = buffer.read_pod<int32>();
    motor_proportional_recovery_velocity = buffer.read_pod<float32>();
    motor_tau = buffer.read_pod<float32>();
    part_name = buffer.read_pod<int32>();
    on_stopped_event.read(buffer);
    motor_constant_recovery_velocity = buffer.read_pod<float32>();
    motor_min_force = buffer.read_pod<float32>();
    max_friction_torque = buffer.read_pod<float32>();
    buffer.skip(4);
    on_start_event.read(buffer);
    motor_max_force_mass_scalar_override = buffer.read_pod<float32>();
    motor_max_force = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

