void ADFTypes::BarkConstants::read(IO::File& buffer) {
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        UseObjectNormal = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        UseTextureBlend1 = (bitfield_value >> 1) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
    BlendUpInfluence1 = buffer.read_pod<float32>();
    BlendUpNormal1 = buffer.read_pod<float32>();
    BlendUpContrast1 = buffer.read_pod<float32>();
    BlendUpShift1 = buffer.read_pod<float32>();
    BlendMaskBias1 = buffer.read_pod<float32>();
    BlendMaskBreakup1 = buffer.read_pod<float32>();
    BlendMaskContrast1 = buffer.read_pod<float32>();
    BlendUvMultiplier1 = buffer.read_pod<float32>();
    OverlayHeightInfluence = buffer.read_pod<float32>();
    OverlayHeightMapInfluence = buffer.read_pod<float32>();
    OverlayMaskInfluence = buffer.read_pod<float32>();
    OverlayShift = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        OverlayColor[i] = buffer.read_pod<float32>();
    }
    OverlayBrightness = buffer.read_pod<float32>();
    OverlayGloss = buffer.read_pod<float32>();
    OverlayMetallic = buffer.read_pod<float32>();
    OverlayReflectivity = buffer.read_pod<float32>();
    OverlayRoughness = buffer.read_pod<float32>();
    OverlayDiffuseWrap = buffer.read_pod<float32>();
    OverlayEmissive = buffer.read_pod<float32>();
    OverlayTransmission = buffer.read_pod<float32>();
    OverlayClearCoat = buffer.read_pod<float32>();
    OverlayUpInfluence = buffer.read_pod<float32>();
    PlacedInstanceTerrainTintAmount = buffer.read_pod<float32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        NoFade = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        UseWaterFog = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        LowResShadows = (bitfield_value >> 2) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
}

