void ADFTypes::CHandGrenadeData::read(IO::File& buffer) {
    __SubObjects.read(buffer);
    despawn_time = buffer.read_pod<float32>();
    almost_detonate_time = buffer.read_pod<float32>();
    detonate_event.read(buffer);
    bounce_velocity_damp_factor = buffer.read_pod<float32>();
    collision = buffer.read_pod<int32>();
    on_settle_event.read(buffer);
    lifetime = buffer.read_pod<float32>();
    can_be_caught = buffer.read_pod<int32>();
    can_be_remote_activated = buffer.read_pod<int32>();
    increase_gravity_after_time = buffer.read_pod<float32>();
    catch_act = buffer.read_pod<int32>();
    detonate_on_impact = buffer.read_pod<int32>();
    is_sticky = buffer.read_pod<int32>();
    buffer.skip(4);
    on_stick_static_event.read(buffer);
    despawns_after_detonation = buffer.read_pod<int32>();
    settle_time = buffer.read_pod<float32>();
    force_pulse_ref.read(buffer);
    throw_on_spawn = buffer.read_pod<int32>();
    buffer.skip(4);
    on_stick_dynamic_event.read(buffer);
    on_bounce_ground_event.read(buffer);
    on_remote_activate_event.read(buffer);
    random_lifetime = buffer.read_pod<float32>();
    buffer.skip(4);
    clone_factory_ref.read(buffer);
    min_velocity_bounce_sound = buffer.read_pod<float32>();
    buffer.skip(4);
    on_caught_event.read(buffer);
    change_owner_on_rethrow = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        thrower_blackboard_counter = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_bounce_event.read(buffer);
    settle_speed_threshold = buffer.read_pod<float32>();
    detonate_on_settle = buffer.read_pod<int32>();
    despawn_event.read(buffer);
    bounce_ground_angle = buffer.read_pod<float32>();
    buffer.skip(4);
    on_stick_event.read(buffer);
    detonates_automatically = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_almost_detonate_event.read(buffer);
    max_velocity_bounce_sound = buffer.read_pod<float32>();
    gravity_increase_per_second = buffer.read_pod<float32>();
    lifetime_on_throw = buffer.read_pod<int32>();
    buffer.skip(4);
    on_detonate_event.read(buffer);
    use_raycast_for_characters = buffer.read_pod<int32>();
    buffer.skip(4);
    on_stick_character_event.read(buffer);
    max_gravity_factor = buffer.read_pod<float32>();
    buffer.skip(4);
}

