void ADFTypes::PointConstraint::read(IO::File& buffer) {
    source_joint.read(buffer);
    target_joint.read(buffer);
    source_joint_index = buffer.read_pod<int8>();
    target_joint_index = buffer.read_pod<int8>();
    buffer.skip(2);
    for(int i = 0; i < 3; ++i) {
        translation_offset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        constrained_translation_axes[i] = buffer.read_pod<int8>();
    }
    buffer.skip(1);
}

void ADFTypes::PointConstraint::print(std::ostream &out) const {
    out << "source_joint: ";
    source_joint.print(out);
    out << "\n";
    out << "target_joint: ";
    target_joint.print(out);
    out << "\n";
    out << "source_joint_index: " << source_joint_index << "\n";
    out << "target_joint_index: " << target_joint_index << "\n";
    out << "translation_offset: \n";
    translation_offset.print(out);
    out << "\n";
    out << "constrained_translation_axes: \n";
    constrained_translation_axes.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::PointConstraint::to_json() const {
    nlohmann::json _res;
    _res["source_joint"] = source_joint.to_json();
    _res["target_joint"] = target_joint.to_json();
    _res["source_joint_index"] = source_joint_index;
    _res["target_joint_index"] = target_joint_index;
    _res["translation_offset"] = translation_offset.to_json();
    _res["constrained_translation_axes"] = constrained_translation_axes.to_json();
    return _res;
}

